INSERT INTO translations (locale, key, value) VALUES ('en', 'faq.title', 'Frequently asked questions') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'faq.questions', '["What are the check-in and check-out times at Crooked House?","How much does it cost to stay at Crooked House?","What activities can be done at Crooked House?","How far is Crooked House from the center of Grandola ed Uniti?","Is Crooked House a family-friendly property?","What is the tourist tax?","Why do I need to enter my personal data?","Is a car necessary?","Is parking complicated?","Where is Crooked House located?","How can Crooked House be reached?","Is it possible to reach Crooked House directly by car?","Is the route suitable for people with reduced mobility?"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'faq.answers', '["Check-in at Crooked House is available from 3:30 PM; check-out is expected by 10:00 AM.","The price may vary depending on the stay, such as the dates and applicable conditions. To find out the price, enter the stay dates.","The following activities and services are available at Crooked House (some may be subject to a fee):\n- Cycling\n- Hiking\n- Tennis court (distance 2.6 km)\n- Golf course (distance 5.8 km)","Crooked House is 1.9 km from the center of Grandola ed Uniti.","Yes, Crooked House is popular with guests booking family stays.","The tourist tax is a municipal contribution applied to guests staying in accommodation facilities in the Municipality of Grandola ed Uniti (CO). The amount is calculated per person per night, according to the type of facility and the rates established by the Municipality.\n\nFor other accommodation facilities, the rate published by the Municipality is **€2.00 per person per night**, subject to any updates. Possible exemptions are provided for according to municipal regulations. The tax is collected by the accommodation facility and subsequently paid to the Municipality.\n\nFor more information, visit the official website of the [Municipality of Grandola ed Uniti](https://www.comune.grandolaeduniti.co.it/c013111/zf/index.php/servizi-aggiuntivi/index/index/idtesto/25).","Your personal data is necessary to manage the booking, identify guests, and fulfill legal obligations, in particular under Art. 109 of the T.U.L.P.S. (Royal Decree of 18 June 1931, no. 773), regarding the communication of guests'' details to the Questura via the Alloggiati Web portal. Data will be processed in compliance with EU Regulation 2016/679 (GDPR) and Legislative Decree 196/2003, as amended by Legislative Decree 101/2018, concerning personal data protection.","Naggio is connected to Menaggio, a starting point for numerous destinations, via bus with only two daily trips. For this reason, having a car allows for greater freedom and flexibility during your stay.","No, parking is not particularly complicated: several free municipal parking lots are available. Additionally, the property offers a parking space in a private garage, suitable for small and medium-sized cars, with a maximum length of 4.4 m and a maximum width of 1.8 m.","Crooked House is located in the heart of the historic center, in a characteristic pedestrian area free of vehicular traffic, ideal for those wishing to stay in a quiet and authentic environment.","The property is reachable on foot via a short path through the historic center. The route follows a cobblestone street, along which you may encounter some steps.","No, Crooked House is located in a pedestrian area free of vehicular traffic. The final stretch to reach the property must be traveled on foot.","The access route features cobblestone paving and may include some steps. These features could make access difficult for people with reduced mobility."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'servicesPage.body', 'We offer a breakfast and meal service designed to make your stay even more pleasant. You can start the day with a delicious breakfast and enjoy moments of relaxation savoring carefully prepared dishes in a warm and welcoming atmosphere.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'servicesPage.sectionTitles', '["Breakfast and meals","Quality, training, and safety"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'servicesPage.sectionBodies', '["To make your stay even more pleasant, we offer breakfast and dinner service upon request, designed to make you feel at home.\n\nYou can start the day with a delicious breakfast and end it with a carefully prepared dinner, in a warm, welcoming, and cozy atmosphere.\n\nFor those who love to explore the area, a packed lunch service is also available upon request, ideal to take with you during trips and excursions.\n\nService costs and booking methods are available directly at the property.\n\nInformation on food intolerances\n\nThe facility does not have suitable environments and equipment to guarantee the absence of cross-contamination. Therefore, we cannot ensure the preparation of specific meals for people with gluten or lactose intolerances.","Our facility is committed to ensuring high standards of quality, safety, and professionalism, in compliance with current regulations and through constant skill updates.\n\nThe training and qualifications obtained testify to our attention to detail, the correct management of services, and the quality of the experience offered to our guests.\n\nCertificates and professional qualifications\nHACCP training\nCertificate no. 56560 of 08/09/2025.\nAuthorization for the service of food and beverages and the conduct of commercial activities in the food sector\nCompetence certificate no. E1.2025.1069853\nSection ID: 137540 of 08/10/2025.\nPastry training\nPastry course obtained at the Accademia Italiana Chef in Milan, in November/December 2025."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'privacyPage.title', 'Privacy policy') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'privacyPage.sectionTitles', '["PRIVACY POLICY"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'privacyPage.sectionBodies', '["PRIVACY POLICY\nProcessing of users'' and guests'' personal data\n\nIn accordance with Regulation (EU) 2016/679 (GDPR) and applicable Italian law, this privacy policy describes the methods of processing the personal data of users visiting the website and guests who book or stay at our holiday home.\n\n1. Data Controller\nThe data controller is:\n\n[First and last name of the owner / Company name]\nName of the facility: [Name of the holiday home]\nAddress: [Full address of the facility]\nTax Code / VAT Number: [Insert applicable data]\nE-mail: [Contact e-mail address]\nTelephone: [Phone number]\n\nFor any information relating to the processing of personal data or to exercise the rights provided by law, you may contact the controller using the contact details indicated above.\n\n2. Types of personal data processed\nIn the context of website navigation, booking management, and the provision of accommodation services, the following categories of data may be processed:\n\nIdentification data: name, surname, nationality, and other data necessary to identify guests.\nIdentity document data: exclusively those necessary for legal compliance related to hospitality.\nContact data: e-mail address and telephone number.\nBooking data: dates of stay, number of guests, requests received, confirmations, modifications, and cancellations.\nAdministrative and payment data: information necessary for managing fees, payments, and tax and accounting obligations.\nData contained in communications: information voluntarily transmitted by users via e-mail, telephone, or contact forms that may be present on the website.\nTechnical navigation data: information generated by IT systems and communication protocols during site browsing, such as IP address, date and time of access, information on the browser and requests made, within the limits in which they are actually collected.\nThe facility does not request personal data not relevant to the purposes of the processing. Users are advised not to transmit sensitive or special information unless strictly necessary and an adequate legal basis exists.\n\n3. Purposes and legal bases of the processing\nPersonal data are processed for the following purposes:\n\na) Management of information requests and bookings\n\nTo respond to user requests, verify availability, make proposals, confirm bookings, and manage any changes or cancellations.\n\nLegal basis: performance of pre-contractual measures requested by the data subject and performance of the contract, pursuant to Article 6, paragraph 1, letter b), of the GDPR.\n\nb) Management of the stay and related services\n\nTo organize the welcome, communicate information necessary for the stay, and manage services requested by guests.\n\nLegal basis: performance of the contract and, where applicable, compliance with legal obligations.\n\nc) Administrative and regulatory compliance\n\nTo comply with the obligations provided by the legislation applicable to accommodation facilities, including obligations relating to the communication of guests'' personal details to the competent authorities, as well as tax and accounting obligations.\n\nLegal basis: compliance with legal obligations pursuant to Article 6, paragraph 1, letter c), of the GDPR.\n\nd) Payment management and protection of rights\n\nTo verify payments, manage any disputes, and protect the facility''s rights in extrajudicial or judicial proceedings, when necessary.\n\nLegal basis: performance of the contract, compliance with legal obligations, or the legitimate interest of the controller, depending on the specific case.\n\ne) Security and functioning of the website\n\nTo ensure the correct functioning of the site, prevent unauthorized access, and manage any technical problems.\n\nLegal basis: legitimate interest of the controller, where applicable, respecting the rights and freedoms of the data subjects.\n\nNo promotional communications or profiling activities are carried out based on the information currently available. Should such activities be introduced, the privacy policy will be updated and any consent required by law will be requested.\n\n4. Bookings via the website and external platforms\nBookings can be made directly through the facility''s channels or through online mediation and booking platforms.\n\nIn the case of direct booking, personal data are processed by the controller to manage the request, conclude the contract, and organize the stay.\n\nIn the case of booking through external platforms, data may also be collected and processed by the platform concerned, according to its own contractual terms and privacy policies.\n\nThe platform and the facility may act as independent data controllers for their respective purposes. Information regarding the processing carried out by the platform is available in the relevant privacy policy.\n\n5. Nature of data provision\nProviding the data necessary for booking management, the provision of the stay, and compliance with legal obligations is necessary for the respective purposes.\n\nFailure to provide indispensable data may result in the impossibility of confirming the booking, providing the requested service, or complying with regulatory obligations.\n\nProviding additional and non-necessary information is optional.\n\n6. Processing methods and security\nPersonal data are processed using IT tools and, where necessary, paper documentation, according to procedures appropriate to the purposes pursued.\n\nThe controller adopts technical and organizational measures proportionate to the risk to protect personal data from loss, destruction, unauthorized access, disclosure, or unlawful use.\n\nData are accessible exclusively to the controller and any authorized or appointed persons, within the limits of their respective competencies.\n\n7. Communication of data\nPersonal data may be communicated, within the limits of the indicated purposes, to:\n\npublic authorities and competent bodies, in cases provided by law;\ntax consultants, accountants, and appointed professionals;\nbanking institutions and payment service providers;\nhosting, maintenance, and IT assistance providers;\nbooking platforms and intermediaries used by the guest;\nother providers involved in managing the stay, when necessary.\nThe recipients act, depending on the case, as independent controllers or data processors.\n\nData are not indiscriminately disseminated to the public.\n\n8. Transfer of data outside the European Economic Area\nShould a transfer of personal data to countries outside the European Economic Area occur through external platforms or service providers, the transfer will take place in compliance with the conditions and guarantees provided by the GDPR.\n\nInformation regarding any transfers actually carried out may be requested from the controller.\n\n9. Retention period\nPersonal data are kept for the time necessary to achieve the purposes for which they were collected and, subsequently, for the periods provided for by applicable law or necessary to protect the rights of the controller.\n\nIn particular:\n\ndata relating to requests and bookings are kept for the time necessary to manage the relationship and any subsequent obligations;\nadministrative, tax, and accounting data are kept for the terms provided by applicable law;\ndata relating to public safety obligations are kept and managed according to the specific applicable provisions;\ntechnical navigation data are kept for the period necessary for the purposes of security and the functioning of the site, according to the policies actually adopted by the service provider.\nSpecific retention periods are defined based on the category of data, legal obligations, and the characteristics of the systems used.\n\n10. Cookies and navigation data\nAccording to the information currently available, the site does not use additional statistical analysis, advertising profiling, or marketing tools.\n\nHowever, navigation may involve the processing of technical data by the server hosting the site or the use of technical cookies necessary for its operation.\n\nThe actual technologies used, including those potentially integrated into the booking system, must be verified before the final publication of this privacy policy.\n\nIf the site uses only technical cookies, the relevant information may be included in this privacy policy. If tracking tools that require prior consent are used, the information and consent management methods provided by applicable law will be adopted.\n\n11. Rights of the data subjects\nData subjects may exercise, in the cases and within the limits provided by the GDPR, the following rights:\n\nto obtain confirmation of the existence of processing and access to their personal data;\nto request the rectification of inaccurate data or the completion of incomplete data;\nto request the erasure of data, when the requirements are met;\nto request the restriction of processing;\nto object to processing based on legitimate interest, for reasons connected to their particular situation;\nto obtain data portability, in cases provided by law;\nto withdraw consent, if provided, without affecting the lawfulness of the processing prior to the withdrawal;\nto lodge a complaint with the Data Protection Authority.\nRequests can be sent to the controller''s contact details indicated in this privacy policy.\n\n12. Changes to the privacy policy\nThis privacy policy may be updated in the event of regulatory, organizational, or technical changes affecting the processing of personal data.\n\nThe updated version will be published on the facility''s website.\n\nLast updated: 24/10/2026.\n\nFor further information on the processing of personal data, you may contact the controller at the contact details indicated in this privacy policy."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'termsPage.title', 'Terms and conditions') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'termsPage.sectionTitles', '["Cancellation policy","General terms and conditions of stay"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'termsPage.sectionBodies', '["You may cancel the reservation up to 10 days before the scheduled check-in date to receive a full refund of the amount paid.\n\nIn the event of a cancellation made after this deadline, no refund will be provided.","1. Introduction\nThese general conditions govern the procedures for booking, access, stay, and use of the services offered by the accommodation facility.\nConfirmation of the reservation implies that you have read and accepted the conditions set forth in this document, without prejudice to the mandatory provisions provided by current legislation.\n2. Reservations\nReservations can be made through the facility''s official contact channels or via authorized platforms.\nThe reservation is considered confirmed according to the methods communicated at the time of the request and, where applicable, following the payment of the required amount.\nAny special requests must be communicated in advance and will only be considered confirmed upon acceptance by the facility.\n3. Check-in and check-out\nCheck-in and check-out times are communicated at the time of booking or prior to arrival.\nGuests are required to respect the agreed times, unless otherwise agreed upon and previously authorized by the facility.\nAny requests for early arrival or late departure will be assessed based on availability and may incur additional costs if communicated and agreed upon in advance.\n4. Payments\nRates, payment methods, and any amounts to be paid in advance are communicated at the time of booking.\nGuests are required to respect the agreed payment deadlines. Any additional services requested during the stay will be charged according to the rates communicated by the facility.\nAny tourist tax, where applicable, will be charged in accordance with the regulations in force in the relevant Municipality.\n5. Cancellations and refunds\nThe reservation can be cancelled up to 10 days before the scheduled check-in date, with the right to a full refund of the amount paid.\nIn the event of a cancellation made within 9 days of check-in, or in the event of a no-show, no refund will be provided.\nThe cancellation request must be communicated through the channel used for the reservation or via the facility''s official contact details. The date the communication is received will be taken as the reference.\nFor reservations made through external platforms, the specific conditions provided by the platform may also apply, within the limits of their compatibility with the confirmed conditions and current legislation.\n6. Breakfast, meals, and additional services\nBreakfast, dinner, and packed lunch services are available upon request, subject to availability and according to the rates communicated directly by the facility.\nAny special dietary requests must be reported in advance. The facility does not have suitable environments and equipment to guarantee the absence of cross-contamination and, therefore, cannot ensure the preparation of safe meals for people who require a gluten-free or lactose-free diet for medical reasons.\nAdditional services are subject to availability and must be agreed upon in advance.\n7. Rules of conduct\nGuests are invited to maintain respectful behavior towards other guests, staff, environments, and the surrounding context.\nCare must be taken when using the furniture, equipment, and spaces provided, avoiding behaviors that may cause disturbance or compromise the safety and tranquility of the facility.\nAny damage caused intentionally or through negligence may be charged to the person responsible, following verification and in compliance with current legislation.\n8. Cleaning and care of the premises\nThe facility guarantees the cleanliness of the premises and the maintenance of the spaces according to the procedures provided for the service offered.\nGuests are required to use the premises with care and to promptly report any anomalies, malfunctions, or needs encountered during the stay.\n9. Safety and liability\nGuests are required to follow safety indications and any instructions provided by the facility.\nThe facility adopts measures within its competence to ensure a safe and comfortable stay. Liability for any damage, loss, or inconvenience will be assessed according to the circumstances of the case and applicable legal provisions.\nGuests are invited to look after their personal belongings carefully and to promptly report any problems.\n10. Compliance with regulations and personal data\nThe facility collects and processes guests'' personal data exclusively for purposes related to reservation management, service delivery, and legal compliance, in accordance with applicable personal data protection regulations.\n11. Acceptance of the conditions\nConfirmation of the reservation implies that you have read these general conditions, without prejudice to the protections recognized to guests by current legislation.\nFor any clarification regarding reservations, available services, or conditions of stay, guests may contact the facility directly through the official contact details published on the website.\nThe facility reserves the right to update these conditions, provided that the changes shall not retroactively affect the rights arising from reservations already confirmed, within the limits provided by law."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'faq.title', 'Questions fr?quentes') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'faq.questions', '["Quels sont les horaires de check-in et de check-out à Crooked House ?","Combien coûte un séjour à Crooked House ?","Quelles activités peut-on pratiquer à Crooked House ?","À quelle distance se trouve Crooked House du centre de Grandola ed Uniti ?","Crooked House est-il un établissement adapté aux familles ?","Qu''est-ce que la taxe de séjour ?","Pourquoi dois-je saisir mes données personnelles ?","Est-il nécessaire d''avoir une voiture ?","Est-il compliqué de se garer ?","Où se trouve Crooked House ?","Comment se rendre à Crooked House ?","Est-il possible de se rendre à Crooked House directement en voiture ?","Le parcours est-il adapté aux personnes à mobilité réduite ?"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'faq.answers', '["Le check-in à Crooked House est disponible à partir de 15h30 ; le check-out est prévu avant 10h00.","Le prix peut varier en fonction du séjour, par exemple selon les dates et les conditions applicables. Pour connaître le prix, veuillez saisir les dates du séjour.","À Crooked House, les activités et services suivants sont disponibles (certains peuvent être payants) :\n- Cyclisme\n- Randonnée\n- Terrain de tennis (distance 2,6 km)\n- Terrain de golf (distance 5,8 km)","Crooked House se trouve à 1,9 km du centre de Grandola ed Uniti.","Oui, Crooked House est apprécié des clients qui réservent des séjours en famille.","La taxe de séjour est une contribution communale appliquée aux clients séjournant dans les établissements d''hébergement de la commune de Grandola ed Uniti (CO). Le montant est calculé par personne et par nuit, selon le type d''établissement et les tarifs fixés par la commune.\n\nPour les autres établissements d''hébergement, le tarif publié par la commune est de **2,00 € par personne et par nuit**, sous réserve de mises à jour éventuelles. Des exonérations peuvent être prévues selon le règlement municipal. La taxe est perçue par l''établissement d''hébergement et versée ultérieurement à la commune.\n\nPour plus d''informations, consultez le site officiel de la [Commune de Grandola ed Uniti](https://www.comune.grandolaeduniti.co.it/c013111/zf/index.php/servizi-aggiuntivi/index/index/idtesto/25).","Vos données personnelles sont nécessaires pour gérer la réservation, identifier les clients et respecter les obligations légales, notamment l''art. 109 du T.U.L.P.S. (Décret royal du 18 juin 1931, n. 773), relatif à la communication de l''identité des clients à la Questura via le portail Alloggiati Web. Les données seront traitées conformément au Règlement UE 2016/679 (RGPD) et au D.Lgs. 196/2003, tel que modifié par le D.Lgs. 101/2018, concernant la protection des données personnelles.","Naggio est reliée à Menaggio, point de départ pour de nombreuses destinations, par bus avec seulement deux trajets par jour. Pour cette raison, disposer d''une voiture permet de se déplacer avec plus de liberté et de flexibilité pendant le séjour.","Non, se garer n''est pas particulièrement compliqué : plusieurs parkings communaux gratuits sont disponibles. De plus, l''établissement propose une place de stationnement dans un garage privé, adaptée aux voitures de petite et moyenne taille, avec une longueur maximale de 4,4 m et une largeur maximale de 1,8 m.","Crooked House se trouve au cœur du centre historique, dans une zone piétonne caractéristique et dépourvue de circulation automobile, idéale pour ceux qui souhaitent séjourner dans un environnement calme et authentique.","L''établissement est accessible à pied par un court chemin traversant le centre historique. Le trajet se déroule sur une route pavée, sur laquelle on peut rencontrer quelques marches.","Non, Crooked House se trouve dans une zone piétonne dépourvue de circulation automobile. Le dernier tronçon pour atteindre l''établissement doit être parcouru à pied.","Le chemin d''accès présente un revêtement en pavés et peut inclure quelques marches. Ces caractéristiques pourraient rendre l''accès difficile pour les personnes à mobilité réduite."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'servicesPage.body', 'Nous proposons un service de petit-déjeuner et de repas conçu pour rendre votre séjour encore plus agréable. Vous pourrez commencer la journée par un délicieux petit-déjeuner et profiter de moments de détente en savourant des plats préparés avec soin, dans une atmosphère accueillante et familiale.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'servicesPage.sectionTitles', '["Petits-déjeuners et repas","Qualité, formation et sécurité"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'servicesPage.sectionBodies', '["Pour rendre votre séjour encore plus agréable, nous proposons sur demande un service de petit-déjeuner et de dîner, conçu pour vous faire sentir comme à la maison.\n\nVous pourrez commencer la journée par un délicieux petit-déjeuner et la terminer par un dîner préparé avec soin, dans une atmosphère chaleureuse, accueillante et familiale.\n\nPour ceux qui aiment explorer la région, un service de pique-nique est également disponible sur demande, idéal à emporter lors de sorties et d''excursions.\n\nLes tarifs des services et les modalités de réservation sont disponibles directement auprès de l''établissement.\n\nInformations sur les intolérances alimentaires\n\nL''établissement ne dispose pas d''environnements et d''équipements adaptés pour garantir l''absence de contaminations croisées. Par conséquent, nous ne pouvons pas assurer la préparation de repas spécifiques pour les personnes souffrant d''intolérance au gluten ou au lactose.","Notre établissement s''engage à garantir des normes élevées de qualité, de sécurité et de professionnalisme, dans le respect des réglementations en vigueur et grâce à une mise à jour constante des compétences.\n\nLa formation et les qualifications obtenues témoignent de notre attention portée aux détails, à la gestion correcte des services et à la qualité de l''expérience offerte à nos hôtes.\n\nCertificats et qualifications professionnelles\nFormation HACCP\nCertificat n° 56560 du 08/09/2025.\nHabilitation à la distribution d''aliments et de boissons et à l''exercice de l''activité commerciale dans le secteur alimentaire\nCertificat de compétence n° E1.2025.1069853\nID section : 137540 du 08/10/2025.\nFormation en pâtisserie\nCours de pâtisserie obtenu auprès de l''Accademia Italiana Chef de Milan, en novembre/décembre 2025."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'privacyPage.title', 'Politique de confidentialité') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'privacyPage.sectionTitles', '["POLITIQUE DE CONFIDENTIALITÉ"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'privacyPage.sectionBodies', '["POLITIQUE DE CONFIDENTIALITÉ\nTraitement des données personnelles des utilisateurs et des hôtes\n\nConformément au Règlement (UE) 2016/679 (RGPD) et à la réglementation italienne applicable, la présente politique décrit les modalités de traitement des données personnelles des utilisateurs visitant le site internet et des hôtes réservant ou séjournant dans notre maison de vacances.\n\n1. Responsable du traitement\nLe responsable du traitement des données personnelles est :\n\n[Nom et prénom du responsable / Raison sociale]\nNom de l''établissement : [Nom de la maison de vacances]\nAdresse : [Adresse complète de l''établissement]\nCode fiscal / Numéro de TVA : [Insérer la donnée applicable]\nE-mail : [Adresse e-mail de contact]\nTéléphone : [Numéro de téléphone]\n\nPour toute information relative au traitement des données personnelles ou pour exercer les droits prévus par la réglementation, il est possible de contacter le responsable en utilisant les coordonnées indiquées ci-dessus.\n\n2. Types de données personnelles traitées\nDans le cadre de la navigation sur le site, de la gestion des réservations et de la prestation des services de séjour, les catégories de données suivantes peuvent être traitées :\n\nDonnées d''identification : nom, prénom, nationalité et autres données nécessaires pour identifier les hôtes.\nDonnées relatives aux documents d''identité : exclusivement celles nécessaires aux obligations légales liées à l''hébergement.\nDonnées de contact : adresse e-mail et numéro de téléphone.\nDonnées relatives à la réservation : dates du séjour, nombre d''hôtes, demandes reçues, confirmations, modifications et annulations.\nDonnées administratives et de paiement : informations nécessaires à la gestion des honoraires, des paiements et des obligations fiscales et comptables.\nDonnées contenues dans les communications : informations transmises volontairement par les utilisateurs via e-mail, téléphone ou formulaires de contact éventuellement présents sur le site.\nDonnées techniques de navigation : informations générées par les systèmes informatiques et les protocoles de communication lors de la consultation du site, telles que l''adresse IP, la date et l''heure d''accès, les informations sur le navigateur et sur les requêtes effectuées, dans la mesure où elles sont effectivement collectées.\nL''établissement ne demande pas de données personnelles non pertinentes aux finalités du traitement. Les utilisateurs sont invités à ne pas transmettre d''informations sensibles ou particulières, sauf si elles sont strictement nécessaires et qu''une base juridique adéquate existe.\n\n3. Finalités et bases juridiques du traitement\nLes données personnelles sont traitées pour les finalités suivantes :\n\na) Gestion des demandes d''informations et des réservations\n\nPour répondre aux demandes des utilisateurs, vérifier la disponibilité, formuler des propositions, confirmer les réservations et gérer d''éventuelles variations ou annulations.\n\nBase juridique : exécution de mesures précontractuelles demandées par l''intéressé et exécution du contrat, conformément à l''article 6, paragraphe 1, lettre b), du RGPD.\n\nb) Gestion du séjour et des services connexes\n\nPour organiser l''accueil, communiquer les informations nécessaires au séjour et gérer les services demandés par les hôtes.\n\nBase juridique : exécution du contrat et, le cas échéant, respect des obligations légales.\n\nc) Obligations administratives et réglementaires\n\nPour satisfaire aux obligations prévues par la réglementation applicable aux établissements d''hébergement, y compris les obligations relatives à la communication de l''identité des hôtes aux autorités compétentes, ainsi qu''aux obligations fiscales et comptables.\n\nBase juridique : respect d''obligations légales conformément à l''article 6, paragraphe 1, lettre c), du RGPD.\n\nd) Gestion des paiements et protection des droits\n\nPour vérifier les paiements, gérer d''éventuelles contestations et protéger les droits de l''établissement lors de procédures extrajudiciaires ou judiciaires, si nécessaire.\n\nBase juridique : exécution du contrat, respect des obligations légales ou intérêt légitime du responsable, selon le cas concret.\n\ne) Sécurité et fonctionnement du site internet\n\nPour garantir le bon fonctionnement du site, prévenir les accès abusifs et gérer d''éventuels problèmes techniques.\n\nBase juridique : intérêt légitime du responsable, le cas échéant, dans le respect des droits et libertés des personnes concernées.\n\nAucune communication promotionnelle ou activité de profilage n''est effectuée sur la base des informations actuellement disponibles. Si de telles activités étaient introduites, la politique serait mise à jour et les consentements éventuellement prévus par la loi seraient demandés.\n\n4. Réservations via le site et les plateformes externes\nLes réservations peuvent être effectuées directement via les canaux de l''établissement ou par le biais de plateformes de réservation et d''intermédiation en ligne.\n\nEn cas de réservation directe, les données personnelles sont traitées par le responsable pour gérer la demande, conclure le contrat et organiser le séjour.\n\nEn cas de réservation via des plateformes externes, les données peuvent également être collectées et traitées par la plateforme concernée, selon ses propres conditions contractuelles et politiques de confidentialité.\n\nLa plateforme et l''établissement peuvent agir en tant que responsables de traitement indépendants pour leurs finalités respectives. Les informations relatives au traitement effectué par la plateforme sont disponibles dans sa politique de confidentialité correspondante.\n\n5. Nature de la fourniture des données\nLa fourniture des données nécessaires à la gestion de la réservation, à la prestation du séjour et au respect des obligations légales est nécessaire aux finalités correspondantes.\n\nL''éventuel défaut de fourniture des données indispensables peut entraîner l''impossibilité de confirmer la réservation, de fournir le service demandé ou de respecter les obligations réglementaires.\n\nLa fourniture d''informations supplémentaires et non nécessaires est facultative.\n\n6. Modalités de traitement et sécurité\nLes données personnelles sont traitées au moyen d''outils informatiques et, si nécessaire, de documents papier, selon des procédures adaptées aux finalités poursuivies.\n\nLe responsable adopte des mesures techniques et organisationnelles proportionnées au risque pour protéger les données personnelles contre la perte, la destruction, l''accès non autorisé, la divulgation ou l''utilisation illicite.\n\nLes données sont accessibles exclusivement au responsable et aux éventuels sujets autorisés ou mandatés, dans la limite de leurs compétences respectives.\n\n7. Communication des données\nLes données personnelles peuvent être communiquées, dans la limite des finalités indiquées, à :\n\nautorités publiques et organismes compétents, dans les cas prévus par la loi ;\nconseillers fiscaux, experts-comptables et professionnels mandatés ;\nétablissements bancaires et fournisseurs de services de paiement ;\nfournisseurs d''hébergement, de maintenance et d''assistance informatique ;\nplateformes de réservation et intermédiaires utilisés par l''hôte ;\nautres fournisseurs impliqués dans la gestion du séjour, si nécessaire.\nLes destinataires agissent, selon les cas, en tant que responsables de traitement indépendants ou sous-traitants.\n\nLes données ne sont pas diffusées indistinctement au public.\n\n8. Transfert de données hors de l''Espace économique européen\nDans le cas où, par le biais de plateformes externes ou de fournisseurs de services, un transfert de données personnelles vers des pays situés en dehors de l''Espace économique européen aurait lieu, le transfert s''effectuera dans le respect des conditions et des garanties prévues par le RGPD.\n\nLes informations relatives aux éventuels transferts réellement effectués peuvent être demandées au responsable.\n\n9. Durée de conservation\nLes données personnelles sont conservées pendant la durée nécessaire à la réalisation des finalités pour lesquelles elles ont été collectées et, par la suite, pour les périodes prévues par la réglementation applicable ou nécessaires à la protection des droits du responsable.\n\nEn particulier :\n\nles données relatives aux demandes et aux réservations sont conservées pendant la durée nécessaire à la gestion de la relation et des éventuelles obligations ultérieures ;\nles données administratives, fiscales et comptables sont conservées pendant les délais prévus par la réglementation applicable ;\nles données relatives aux obligations de sécurité publique sont conservées et gérées selon les dispositions spécifiques applicables ;\nles données techniques de navigation sont conservées pendant la période nécessaire aux finalités de sécurité et de fonctionnement du site, selon les politiques effectivement adoptées par le fournisseur de services.\nLes durées de conservation spécifiques sont définies en fonction de la catégorie de données, des obligations légales et des caractéristiques des systèmes utilisés.\n\n10. Cookies et données de navigation\nLe site n''utilise pas, selon les informations actuellement disponibles, d''outils supplémentaires d''analyse statistique, de profilage publicitaire ou de marketing.\n\nLa navigation pourrait toutefois entraîner le traitement de données techniques par le serveur qui héberge le site ou l''utilisation de cookies techniques nécessaires à son fonctionnement.\n\nLes technologies réellement utilisées, y compris celles éventuellement intégrées au système de réservation, doivent être vérifiées avant la publication définitive de cette politique.\n\nSi le site utilise exclusivement des cookies techniques, les informations correspondantes pourront être reportées dans la présente politique. Si des outils de suivi nécessitant un consentement préalable sont utilisés, les informations et les modalités de gestion du consentement prévues par la réglementation applicable seront adoptées.\n\n11. Droits des personnes concernées\nLes personnes concernées peuvent exercer, dans les cas et les limites prévus par le RGPD, les droits suivants :\n\nobtenir la confirmation de l''existence d''un traitement et accéder à leurs données personnelles ;\ndemander la rectification de données inexactes ou la complétion de données incomplètes ;\ndemander l''effacement des données, lorsque les conditions sont réunies ;\ndemander la limitation du traitement ;\ns''opposer aux traitements fondés sur l''intérêt légitime, pour des motifs liés à leur situation particulière ;\nobtenir la portabilité des données, dans les cas prévus par la loi ;\nrévoquer le consentement éventuellement donné, sans porter atteinte à la licéité du traitement antérieur à la révocation ;\ndéposer une réclamation auprès de l''Autorité de protection des données.\nLes demandes peuvent être envoyées aux coordonnées du responsable indiquées dans la présente politique.\n\n12. Modifications de la politique\nLa présente politique peut être mise à jour en cas de modifications réglementaires, organisationnelles ou techniques affectant le traitement des données personnelles.\n\nLa version mise à jour sera publiée sur le site internet de l''établissement.\n\nDernière mise à jour : 24/10/2026.\n\nPour plus d''informations sur le traitement des données personnelles, il est possible de contacter le responsable aux coordonnées indiquées dans la présente politique."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'termsPage.title', 'Conditions générales') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'termsPage.sectionTitles', '["Politique d''annulation","Conditions générales de séjour"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'termsPage.sectionBodies', '["Il est possible d''annuler la réservation jusqu''à 10 jours avant la date prévue pour l''arrivée (check-in), en obtenant le remboursement intégral du montant versé.\n\nEn cas d''annulation effectuée au-delà de ce délai, aucun remboursement ne sera prévu.","1. Préambule\nLes présentes conditions générales régissent les modalités de réservation, d''accès, de séjour et d''utilisation des services offerts par l''établissement.\nLa confirmation de la réservation implique la lecture et l''acceptation des conditions énoncées dans le présent document, sans préjudice des dispositions impératives prévues par la réglementation en vigueur.\n2. Réservations\nLes réservations peuvent être effectuées via les canaux de contact officiels de l''établissement ou par le biais de plateformes autorisées.\nLa réservation est considérée comme confirmée selon les modalités communiquées lors de la demande et, le cas échéant, suite au versement du montant demandé.\nToute demande particulière devra être communiquée à l''avance et ne sera considérée comme confirmée qu''après acceptation de la part de l''établissement.\n3. Arrivée (check-in) et départ (check-out)\nLes horaires d''arrivée et de départ sont communiqués lors de la réservation ou avant l''arrivée.\nLes clients sont tenus de respecter les horaires convenus, sauf accord contraire préalablement autorisé par l''établissement.\nToute demande d''arrivée anticipée ou de départ tardif sera évaluée en fonction de la disponibilité et pourra entraîner des frais supplémentaires, si elle est communiquée et convenue à l''avance.\n4. Paiements\nLes tarifs, les modalités de paiement et les éventuels montants à verser à l''avance sont communiqués lors de la réservation.\nLes clients sont tenus de respecter les échéances de paiement convenues. Les éventuels services supplémentaires demandés pendant le séjour seront facturés selon les tarifs communiqués par l''établissement.\nL''éventuelle taxe de séjour, le cas échéant, sera exigée conformément aux dispositions en vigueur dans la commune de référence.\n5. Annulations et remboursements\nLa réservation peut être annulée jusqu''à 10 jours avant la date prévue pour l''arrivée, avec droit au remboursement intégral du montant versé.\nEn cas d''annulation effectuée dans les 9 jours précédant l''arrivée, ou en cas de non-présentation (no-show), aucun remboursement ne sera prévu.\nLa demande d''annulation devra être communiquée via le canal utilisé pour la réservation ou par les coordonnées officielles de l''établissement. La date de réception de la communication fera foi.\nPour les réservations effectuées via des plateformes externes, les conditions spécifiques prévues par la plateforme pourront également s''appliquer, dans la limite de leur compatibilité avec les conditions confirmées et la réglementation en vigueur.\n6. Petit-déjeuner, repas et services supplémentaires\nLes éventuels services de petit-déjeuner, dîner et déjeuner à emporter sont disponibles sur demande, sous réserve de disponibilité et selon les tarifs communiqués directement par l''établissement.\nToute demande alimentaire particulière devra être signalée à l''avance. L''établissement ne dispose pas d''environnements et d''équipements adaptés pour garantir l''absence de contaminations croisées et, par conséquent, ne peut assurer la préparation de repas sûrs pour les personnes nécessitant un régime sans gluten ou sans lactose pour des raisons médicales.\nLes services supplémentaires sont soumis à disponibilité et devront être convenus à l''avance.\n7. Règles de conduite\nLes clients sont invités à adopter un comportement respectueux envers les autres clients, le personnel, les locaux et le contexte environnant.\nIl est demandé d''utiliser avec soin le mobilier, les équipements et les espaces mis à disposition, en évitant tout comportement susceptible de causer un dérangement ou de compromettre la sécurité et la tranquillité de l''établissement.\nTout dommage causé intentionnellement ou par négligence pourra être facturé au responsable, après vérification et dans le respect de la réglementation en vigueur.\n8. Nettoyage et entretien des locaux\nL''établissement garantit le nettoyage des locaux et l''entretien des espaces selon les modalités prévues pour le service offert.\nLes clients sont tenus d''utiliser les locaux avec soin et de signaler rapidement toute anomalie, panne ou besoin constaté pendant le séjour.\n9. Sécurité et responsabilité\nLes clients sont tenus de respecter les consignes de sécurité et les éventuelles instructions fournies par l''établissement.\nL''établissement adopte les mesures relevant de sa compétence pour garantir un séjour sûr et confortable. La responsabilité pour d''éventuels dommages, pertes ou désagréments sera évaluée selon les circonstances de l''espèce et les dispositions légales applicables.\nLes clients sont invités à prendre soin de leurs effets personnels et à signaler rapidement tout problème.\n10. Respect de la réglementation et des données personnelles\nL''établissement collecte et traite les données personnelles des clients exclusivement à des fins liées à la gestion de la réservation, à la prestation de services et aux obligations prévues par la loi, dans le respect de la réglementation applicable en matière de protection des données à caractère personnel.\n11. Acceptation des conditions\nLa confirmation de la réservation implique la lecture des présentes conditions générales, sans préjudice des protections reconnues aux clients par la réglementation en vigueur.\nPour toute précision concernant les réservations, les services disponibles ou les conditions de séjour, les clients peuvent contacter directement l''établissement via les coordonnées officielles publiées sur le site.\nL''établissement se réserve le droit de mettre à jour les présentes conditions, étant entendu que les modifications ne pourront pas porter atteinte rétroactivement aux droits découlant des réservations déjà confirmées, dans les limites prévues par la loi."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'faq.title', 'H?ufig gestellte Fragen') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'faq.questions', '["Wie sind die Check-in- und Check-out-Zeiten in Crooked House?","Wie viel kostet ein Aufenthalt in Crooked House?","Welche Aktivitäten kann man in Crooked House unternehmen?","Wie weit ist Crooked House vom Zentrum von Grandola ed Uniti entfernt?","Ist Crooked House eine familienfreundliche Unterkunft?","Was ist die Kurtaxe?","Warum muss ich meine persönlichen Daten angeben?","Ist ein Auto erforderlich?","Ist das Parken kompliziert?","Wo befindet sich Crooked House?","Wie erreicht man Crooked House?","Kann Crooked House direkt mit dem Auto erreicht werden?","Ist der Weg für Personen mit eingeschränkter Mobilität geeignet?"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'faq.answers', '["Der Check-in in Crooked House ist ab 15:30 Uhr möglich; der Check-out muss bis 10:00 Uhr erfolgen.","Der Preis kann je nach Aufenthalt variieren, zum Beispiel aufgrund der Daten und der geltenden Bedingungen. Um den Preis zu erfahren, geben Sie bitte die Reisedaten ein.","In Crooked House stehen die folgenden Aktivitäten und Dienstleistungen zur Verfügung (einige davon können kostenpflichtig sein):\n- Radfahren\n- Wandern\n- Tennisplatz (Entfernung 2,6 km)\n- Golfplatz (Entfernung 5,8 km)","Crooked House ist 1,9 km vom Zentrum von Grandola ed Uniti entfernt.","Ja, Crooked House ist bei Gästen beliebt, die Familienaufenthalte buchen.","Die Kurtaxe ist ein kommunaler Beitrag, der von Gästen erhoben wird, die in Beherbergungsbetrieben der Gemeinde Grandola ed Uniti (CO) übernachten. Der Betrag wird pro Person und Nacht berechnet, basierend auf der Art der Unterkunft und den von der Gemeinde festgelegten Tarifen.\n\nFür andere Beherbergungsbetriebe beträgt der von der Gemeinde veröffentlichte Tarif **2,00 € pro Person und Nacht**, vorbehaltlich etwaiger Aktualisierungen. Etwaige Befreiungen sind gemäß der kommunalen Verordnung vorgesehen. Die Steuer wird vom Beherbergungsbetrieb eingezogen und anschließend an die Gemeinde abgeführt.\n\nWeitere Informationen finden Sie auf der offiziellen Website der [Gemeinde Grandola ed Uniti](https://www.comune.grandolaeduniti.co.it/c013111/zf/index.php/servizi-aggiuntivi/index/index/idtesto/25).","Ihre personenbezogenen Daten sind erforderlich, um die Buchung zu verwalten, die Gäste zu identifizieren und gesetzliche Verpflichtungen zu erfüllen, insbesondere gemäß Art. 109 des T.U.L.P.S. (Königliches Dekret vom 18. Juni 1931, Nr. 773), der Mitteilung der Personalien der Gäste an die Polizeibehörde (Questura) über das Portal „Alloggiati Web“ betrifft. Die Daten werden in Übereinstimmung mit der EU-Verordnung 2016/679 (DSGVO) und dem Gesetzesdekret 196/2003 in der geänderten Fassung durch das Gesetzesdekret 101/2018 zum Schutz personenbezogener Daten verarbeitet.","Naggio ist mit Menaggio verbunden, einem Ausgangspunkt für zahlreiche Reiseziele, und ist nur zweimal täglich mit dem Bus erreichbar. Aus diesem Grund ermöglicht ein Auto eine größere Freiheit und Flexibilität während des Aufenthalts.","Nein, das Parken ist nicht besonders kompliziert: Es stehen verschiedene kostenlose kommunale Parkplätze zur Verfügung. Darüber hinaus bietet die Unterkunft einen Parkplatz in einer privaten Garage, der für kleine und mittlere Autos mit einer maximalen Länge von 4,4 m und einer maximalen Breite von 1,8 m geeignet ist.","Crooked House befindet sich im Herzen der historischen Altstadt, in einer charakteristischen Fußgängerzone ohne Autoverkehr, ideal für alle, die in einer ruhigen und authentischen Umgebung übernachten möchten.","Die Unterkunft ist zu Fuß über einen kurzen Weg durch die historische Altstadt erreichbar. Der Weg führt über ein Kopfsteinpflaster, auf dem es einige Stufen geben kann.","Nein, Crooked House befindet sich in einer Fußgängerzone ohne Autoverkehr. Das letzte Stück bis zur Unterkunft muss zu Fuß zurückgelegt werden.","Der Zugangsweg hat ein Kopfsteinpflaster und kann einige Stufen enthalten. Diese Merkmale könnten den Zugang für Personen mit eingeschränkter Mobilität erschweren."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'servicesPage.body', 'Wir bieten einen Frühstücks- und Verpflegungsservice an, der deinen Aufenthalt noch angenehmer macht. Du kannst den Tag mit einem leckeren Frühstück beginnen und entspannende Momente bei sorgfältig zubereiteten Gerichten in einer gemütlichen und familiären Atmosphäre genießen.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'servicesPage.sectionTitles', '["Frühstück und Mahlzeiten","Qualität, Ausbildung und Sicherheit"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'servicesPage.sectionBodies', '["Um deinen Aufenthalt noch angenehmer zu gestalten, bieten wir auf Anfrage einen Frühstücks- und Abendessenservice an, damit du dich wie zu Hause fühlst.\n\nDu kannst den Tag mit einem leckeren Frühstück beginnen und ihn mit einem sorgfältig zubereiteten Abendessen in einer warmen, gemütlichen und familiären Atmosphäre ausklingen lassen.\n\nFür alle, die gerne die Umgebung erkunden, bieten wir auf Anfrage auch einen Verpflegungsservice zum Mitnehmen an, ideal für Ausflüge und Wanderungen.\n\nDie Kosten für die Dienstleistungen und die Buchungsmodalitäten sind direkt in der Unterkunft erhältlich.\n\nInformationen zu Lebensmittelunverträglichkeiten\n\nDie Unterkunft verfügt nicht über Räumlichkeiten und Ausrüstungen, die eine Kreuzkontamination vollständig ausschließen können. Daher können wir die Zubereitung spezieller Mahlzeiten für Personen mit Gluten- oder Laktoseintoleranz nicht garantieren.","Unsere Einrichtung setzt sich dafür ein, hohe Qualitäts-, Sicherheits- und Professionalitätsstandards einzuhalten, unter Einhaltung der geltenden Vorschriften und durch ständige Weiterbildung.\n\nDie erworbenen Ausbildungen und Qualifikationen zeugen von unserer Liebe zum Detail, dem korrekten Service-Management und der Qualität des Erlebnisses, das wir unseren Gästen bieten.\n\nBerufliche Zertifikate und Qualifikationen\nHACCP-Schulung\nZertifikat Nr. 56560 vom 08.09.2025.\nBerechtigung zur Ausgabe von Lebensmitteln und Getränken sowie zur Ausübung des Lebensmittelhandels\nKompetenznachweis Nr. E1.2025.1069853\nSektions-ID: 137540 vom 08.10.2025.\nPatisserie-Ausbildung\nPatisserie-Kurs absolviert an der Accademia Italiana Chef in Mailand, im November/Dezember 2025."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'privacyPage.title', 'Datenschutzerklärung') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'privacyPage.sectionTitles', '["DATENSCHUTZERKLÄRUNG"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'privacyPage.sectionBodies', '["DATENSCHUTZERKLÄRUNG\nVerarbeitung personenbezogener Daten von Nutzern und Gästen\n\nGemäß der Verordnung (EU) 2016/679 (DSGVO) und der geltenden italienischen Gesetzgebung beschreibt diese Datenschutzerklärung die Art und Weise der Verarbeitung personenbezogener Daten von Nutzern, die die Website besuchen, und von Gästen, die in unserer Ferienunterkunft buchen oder dort übernachten.\n\n1. Verantwortlicher für die Datenverarbeitung\nDer Verantwortliche für die Verarbeitung personenbezogener Daten ist:\n\n[Vor- und Nachname des Verantwortlichen / Firmenname]\nName der Unterkunft: [Name der Ferienunterkunft]\nAdresse: [Vollständige Adresse der Unterkunft]\nSteuernummer / Umsatzsteuer-Identifikationsnummer: [Zutreffenden Wert einfügen]\nE-Mail: [Kontakt-E-Mail-Adresse]\nTelefon: [Telefonnummer]\n\nFür alle Informationen bezüglich der Verarbeitung personenbezogener Daten oder zur Ausübung der gesetzlich vorgesehenen Rechte können Sie den Verantwortlichen unter den oben angegebenen Kontaktdaten kontaktieren.\n\n2. Arten der verarbeiteten personenbezogenen Daten\nIm Rahmen des Surfens auf der Website, der Verwaltung von Buchungen und der Erbringung von Übernachtungsdienstleistungen können die folgenden Datenkategorien verarbeitet werden:\n\nIdentifikationsdaten: Name, Vorname, Nationalität und andere zur Identifizierung der Gäste erforderliche Daten.\nDaten zu Identitätsdokumenten: ausschließlich die für die gesetzlichen Verpflichtungen im Zusammenhang mit der Beherbergung erforderlichen Daten.\nKontaktdaten: E-Mail-Adresse und Telefonnummer.\nBuchungsdaten: Aufenthaltsdaten, Anzahl der Gäste, erhaltene Anfragen, Bestätigungen, Änderungen und Stornierungen.\nAdministrative und Zahlungsdaten: Informationen, die für die Verwaltung von Gebühren, Zahlungen sowie steuerlichen und buchhalterischen Verpflichtungen erforderlich sind.\nIn der Kommunikation enthaltene Daten: Informationen, die Nutzer freiwillig per E-Mail, Telefon oder über die eventuell auf der Website vorhandenen Kontaktformulare übermitteln.\nTechnische Navigationsdaten: vom IT-System und den Kommunikationsprotokollen während des Website-Besuchs generierte Informationen, wie z. B. IP-Adresse, Datum und Uhrzeit des Zugriffs, Informationen zum Browser und zu den durchgeführten Anfragen, soweit diese tatsächlich erhoben werden.\nDie Unterkunft fordert keine personenbezogenen Daten an, die nicht für die Zwecke der Verarbeitung relevant sind. Die Nutzer werden gebeten, keine sensiblen oder besonderen Informationen zu übermitteln, es sei denn, dies ist zwingend erforderlich und es liegt eine angemessene Rechtsgrundlage vor.\n\n3. Zwecke und Rechtsgrundlagen der Verarbeitung\nDie personenbezogenen Daten werden für die folgenden Zwecke verarbeitet:\n\na) Verwaltung von Informationsanfragen und Buchungen\n\nUm auf Anfragen der Nutzer zu antworten, die Verfügbarkeit zu prüfen, Angebote zu erstellen, Buchungen zu bestätigen und etwaige Änderungen oder Stornierungen zu verwalten.\n\nRechtsgrundlage: Durchführung vorvertraglicher Maßnahmen auf Wunsch der betroffenen Person und Vertragserfüllung gemäß Artikel 6 Absatz 1 Buchstabe b) der DSGVO.\n\nb) Verwaltung des Aufenthalts und der damit verbundenen Dienstleistungen\n\nUm den Empfang zu organisieren, die für den Aufenthalt notwendigen Informationen zu übermitteln und die von den Gästen angeforderten Dienstleistungen zu verwalten.\n\nRechtsgrundlage: Vertragserfüllung und, sofern anwendbar, Erfüllung gesetzlicher Pflichten.\n\nc) Administrative und rechtliche Verpflichtungen\n\nUm die im Rahmen der für Beherbergungsbetriebe geltenden Vorschriften vorgesehenen Verpflichtungen zu erfüllen, einschließlich der Verpflichtungen zur Meldung der Personalien der Gäste an die zuständigen Behörden sowie der steuerlichen und buchhalterischen Pflichten.\n\nRechtsgrundlage: Erfüllung rechtlicher Verpflichtungen gemäß Artikel 6 Absatz 1 Buchstabe c) der DSGVO.\n\nd) Zahlungsmanagement und Wahrung von Rechten\n\nUm Zahlungen zu überprüfen, etwaige Beanstandungen zu verwalten und die Rechte der Unterkunft im außergerichtlichen oder gerichtlichen Verfahren zu wahren, wenn dies erforderlich ist.\n\nRechtsgrundlage: Vertragserfüllung, Erfüllung gesetzlicher Pflichten oder berechtigtes Interesse des Verantwortlichen, je nach konkretem Einzelfall.\n\ne) Sicherheit und Betrieb der Website\n\nUm den ordnungsgemäßen Betrieb der Website zu gewährleisten, unbefugte Zugriffe zu verhindern und etwaige technische Probleme zu beheben.\n\nRechtsgrundlage: Berechtigtes Interesse des Verantwortlichen, sofern anwendbar, unter Wahrung der Rechte und Freiheiten der betroffenen Personen.\n\nEs erfolgen keine Werbekommunikation oder Profiling-Aktivitäten auf der Grundlage der derzeit verfügbaren Informationen. Sollten solche Aktivitäten eingeführt werden, wird die Datenschutzerklärung aktualisiert und die gesetzlich vorgesehenen Einwilligungen werden eingeholt.\n\n4. Buchungen über die Website und externe Plattformen\nBuchungen können direkt über die Kanäle der Unterkunft oder über Online-Vermittlungs- und Buchungsplattformen vorgenommen werden.\n\nIm Falle einer direkten Buchung werden die personenbezogenen Daten vom Verantwortlichen verarbeitet, um die Anfrage zu bearbeiten, den Vertrag abzuschließen und den Aufenthalt zu organisieren.\n\nIm Falle einer Buchung über externe Plattformen können die Daten auch von der jeweiligen Plattform gemäß deren eigenen Vertragsbedingungen und Datenschutzerklärungen erhoben und verarbeitet werden.\n\nDie Plattform und die Unterkunft können als eigenständige Verantwortliche für ihre jeweiligen Zwecke handeln. Informationen über die durch die Plattform durchgeführte Verarbeitung sind in der jeweiligen Datenschutzerklärung verfügbar.\n\n5. Art der Datenübermittlung\nDie Übermittlung der für die Verwaltung der Buchung, die Erbringung des Aufenthalts und die Erfüllung gesetzlicher Verpflichtungen erforderlichen Daten ist für die entsprechenden Zwecke notwendig.\n\nEine etwaige Nichtübermittlung der unverzichtbaren Daten kann dazu führen, dass die Buchung nicht bestätigt, die angeforderte Dienstleistung nicht erbracht oder die gesetzlichen Verpflichtungen nicht erfüllt werden können.\n\nDie Übermittlung weiterer, nicht erforderlicher Informationen ist freiwillig.\n\n6. Art und Weise der Verarbeitung und Sicherheit\nDie personenbezogenen Daten werden mittels IT-Instrumenten und, falls erforderlich, in Papierform gemäß Verfahren verarbeitet, die für die verfolgten Zwecke angemessen sind.\n\nDer Verantwortliche trifft angemessene technische und organisatorische Maßnahmen im Verhältnis zum Risiko, um personenbezogene Daten vor Verlust, Zerstörung, unbefugtem Zugriff, Offenlegung oder missbräuchlicher Verwendung zu schützen.\n\nDie Daten sind ausschließlich dem Verantwortlichen und etwaigen autorisierten oder beauftragten Personen im Rahmen ihrer jeweiligen Kompetenzen zugänglich.\n\n7. Weitergabe von Daten\nDie personenbezogenen Daten können im Rahmen der angegebenen Zwecke an folgende Empfänger weitergegeben werden:\n\nöffentliche Behörden und zuständige Stellen im Rahmen der gesetzlichen Bestimmungen;\nSteuerberater und beauftragte Fachleute;\nBankinstitute und Zahlungsdienstleister;\nHosting-Anbieter, Wartungs- und IT-Support-Dienstleister;\nBuchungsplattformen und vom Gast genutzte Vermittler;\nandere an der Verwaltung des Aufenthalts beteiligte Anbieter, sofern erforderlich.\nDie Empfänger agieren je nach Fall als eigenständige Verantwortliche oder als Auftragsverarbeiter.\n\nDie Daten werden nicht wahllos der Öffentlichkeit zugänglich gemacht.\n\n8. Datenübermittlung in Länder außerhalb des Europäischen Wirtschaftsraums\nSollte über externe Plattformen oder Dienstleister eine Übermittlung personenbezogener Daten in Länder außerhalb des Europäischen Wirtschaftsraums erfolgen, geschieht dies unter Einhaltung der im Rahmen der DSGVO vorgesehenen Bedingungen und Garantien.\n\nInformationen über tatsächlich durchgeführte Übermittlungen können beim Verantwortlichen angefragt werden.\n\n9. Speicherdauer\nDie personenbezogenen Daten werden so lange gespeichert, wie es für die Erreichung der Zwecke, für die sie erhoben wurden, erforderlich ist, und danach für die Zeiträume, die durch die geltende Gesetzgebung vorgeschrieben sind oder zur Wahrung der Rechte des Verantwortlichen notwendig sind.\n\nInsbesondere:\n\nDaten zu Anfragen und Buchungen werden für die Zeit aufbewahrt, die für die Verwaltung des Verhältnisses und etwaiger nachfolgender Verpflichtungen erforderlich ist;\nadministrative, steuerliche und buchhalterische Daten werden gemäß den in der geltenden Gesetzgebung vorgesehenen Fristen aufbewahrt;\nDaten im Zusammenhang mit öffentlich-rechtlichen Sicherheitsverpflichtungen werden gemäß den geltenden spezifischen Bestimmungen aufbewahrt und verwaltet;\ntechnische Navigationsdaten werden für den Zeitraum aufbewahrt, der für die Zwecke der Sicherheit und des Betriebs der Website erforderlich ist, gemäß den tatsächlich vom Dienstanbieter angewandten Richtlinien.\nDie spezifischen Aufbewahrungsfristen werden basierend auf der Datenkategorie, den gesetzlichen Verpflichtungen und den Merkmalen der verwendeten Systeme festgelegt.\n\n10. Cookies und Navigationsdaten\nDie Website verwendet nach derzeitig verfügbaren Informationen keine zusätzlichen Instrumente zur statistischen Analyse, zum Werbeprofiling oder zum Marketing.\n\nDas Surfen könnte jedoch die Verarbeitung technischer Daten durch den Server, auf dem die Website gehostet wird, oder die Verwendung technisch notwendiger Cookies für den Betrieb der Website beinhalten.\n\nDie tatsächlich verwendeten Technologien, einschließlich der eventuell in das Buchungssystem integrierten, müssen vor der endgültigen Veröffentlichung dieser Datenschutzerklärung überprüft werden.\n\nFalls die Website ausschließlich technische Cookies verwendet, können die entsprechenden Informationen in dieser Datenschutzerklärung aufgeführt werden. Sollten Tracking-Instrumente verwendet werden, die eine vorherige Einwilligung erfordern, werden die in der geltenden Gesetzgebung vorgesehenen Informationen und Verfahren zur Einwilligungserteilung angewandt.\n\n11. Rechte der betroffenen Personen\nDie betroffenen Personen können im Rahmen der in der DSGVO vorgesehenen Fälle und Grenzen folgende Rechte ausüben:\n\nBestätigung über die Vorhandensein einer Verarbeitung zu erhalten und auf ihre personenbezogenen Daten zuzugreifen;\ndie Berichtigung unrichtiger Daten oder die Ergänzung unvollständiger Daten zu verlangen;\ndie Löschung der Daten zu verlangen, sofern die Voraussetzungen hierfür vorliegen;\ndie Einschränkung der Verarbeitung zu verlangen;\nWiderspruch gegen die Verarbeitung aus Gründen einzulegen, die sich aus ihrer besonderen Situation ergeben, wenn diese auf einem berechtigten Interesse beruht;\ndie Übertragbarkeit der Daten in den gesetzlich vorgesehenen Fällen zu erhalten;\ndie erteilte Einwilligung zu widerrufen, ohne die Rechtmäßigkeit der vor dem Widerruf erfolgten Verarbeitung zu berühren;\neine Beschwerde bei der Datenschutzbehörde einzureichen.\nAnfragen können an die im Rahmen dieser Datenschutzerklärung angegebenen Kontaktdaten des Verantwortlichen gesendet werden.\n\n12. Änderungen der Datenschutzerklärung\nDiese Datenschutzerklärung kann im Falle von regulatorischen, organisatorischen oder technischen Änderungen, die die Verarbeitung personenbezogener Daten beeinflussen, aktualisiert werden.\n\nDie aktualisierte Version wird auf der Website der Unterkunft veröffentlicht.\n\nLetzte Aktualisierung: 24.10.2026.\n\nFür weitere Informationen zur Verarbeitung personenbezogener Daten können Sie den Verantwortlichen unter den in dieser Datenschutzerklärung angegebenen Kontaktdaten kontaktieren."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'termsPage.title', 'Allgemeine Geschäftsbedingungen') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'termsPage.sectionTitles', '["Stornierungsbedingungen","Allgemeine Geschäftsbedingungen für den Aufenthalt"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'termsPage.sectionBodies', '["Eine Stornierung der Buchung ist bis zu 10 Tage vor dem geplanten Check-in-Datum möglich, wobei der bereits gezahlte Betrag vollständig erstattet wird.\n\nBei einer Stornierung nach diesem Zeitraum erfolgt keine Rückerstattung.","1. Präambel\nDiese Allgemeinen Geschäftsbedingungen regeln die Modalitäten der Buchung, des Zugangs, des Aufenthalts und der Nutzung der von der Unterkunft angebotenen Dienstleistungen.\nMit der Bestätigung der Buchung erkennt der Gast die in diesem Dokument aufgeführten Bedingungen zur Kenntnis an und akzeptiert diese, vorbehaltlich der zwingenden Bestimmungen der geltenden Rechtsvorschriften.\n2. Buchungen\nBuchungen können über die offiziellen Kontaktkanäle der Unterkunft oder über autorisierte Plattformen vorgenommen werden.\nDie Buchung gilt gemäß den zum Zeitpunkt der Anfrage mitgeteilten Modalitäten als bestätigt und, sofern vorgesehen, nach der Zahlung des geforderten Betrags.\nBesondere Wünsche müssen im Voraus mitgeteilt werden und gelten erst nach ausdrücklicher Bestätigung durch die Unterkunft als bestätigt.\n3. Check-in und Check-out\nDie Check-in- und Check-out-Zeiten werden zum Zeitpunkt der Buchung oder vor der Ankunft mitgeteilt.\nDie Gäste sind verpflichtet, die vereinbarten Zeiten einzuhalten, sofern nicht vorab andere Vereinbarungen mit der Unterkunft getroffen wurden.\nAnfragen für einen frühen Check-in oder einen späten Check-out werden je nach Verfügbarkeit geprüft und können zusätzliche Kosten verursachen, sofern sie im Voraus mitgeteilt und vereinbart wurden.\n4. Zahlungen\nPreise, Zahlungsmodalitäten und etwaige zu leistende Anzahlungen werden zum Zeitpunkt der Buchung mitgeteilt.\nDie Gäste sind verpflichtet, die vereinbarten Zahlungsfristen einzuhalten. Zusätzliche während des Aufenthalts angeforderte Dienstleistungen werden gemäß den von der Unterkunft mitgeteilten Tarifen berechnet.\nDie etwaige Kurtaxe wird, sofern anwendbar, gemäß den geltenden Bestimmungen der jeweiligen Gemeinde erhoben.\n5. Stornierungen und Rückerstattungen\nEine Buchung kann bis zu 10 Tage vor dem geplanten Check-in-Datum storniert werden, mit Anspruch auf vollständige Rückerstattung des gezahlten Betrags.\nBei einer Stornierung innerhalb der 9 Tage vor dem Check-in oder im Falle eines Nichterscheinens (No-Show) erfolgt keine Rückerstattung.\nDer Stornierungswunsch muss über den für die Buchung verwendeten Kanal oder über die offiziellen Kontaktdaten der Unterkunft mitgeteilt werden. Maßgeblich ist das Datum des Eingangs der Mitteilung.\nBei Buchungen über externe Plattformen können auch die spezifischen Bedingungen der Plattform gelten, sofern diese mit den bestätigten Bedingungen und der geltenden Rechtslage vereinbar sind.\n6. Frühstück, Mahlzeiten und Zusatzleistungen\nFrühstück, Abendessen und Lunchpakete sind auf Anfrage, nach Verfügbarkeitsprüfung und gemäß den direkt von der Unterkunft mitgeteilten Tarifen erhältlich.\nBesondere Ernährungswünsche müssen im Voraus mitgeteilt werden. Die Unterkunft verfügt nicht über geeignete Räumlichkeiten und Ausrüstungen, um die Abwesenheit von Kreuzkontaminationen zu garantieren, und kann daher nicht die Zubereitung sicherer Mahlzeiten für Personen garantieren, die aus medizinischen Gründen eine gluten- oder laktosefreie Ernährung benötigen.\nZusatzleistungen unterliegen der Verfügbarkeit und müssen im Voraus vereinbart werden.\n7. Verhaltensregeln\nDie Gäste werden gebeten, sich gegenüber anderen Gästen, dem Personal, der Umgebung und dem Kontext respektvoll zu verhalten.\nDie zur Verfügung gestellten Möbel, Geräte und Räumlichkeiten sind pfleglich zu behandeln. Verhalten, das die Sicherheit oder die Ruhe der Unterkunft beeinträchtigen könnte, ist zu unterlassen.\nEtwaige vorsätzlich oder fahrlässig verursachte Schäden können dem Verantwortlichen nach Prüfung und unter Einhaltung der geltenden Rechtsvorschriften in Rechnung gestellt werden.\n8. Reinigung und Pflege der Räumlichkeiten\nDie Unterkunft garantiert die Sauberkeit der Räumlichkeiten und die Instandhaltung der Flächen gemäß den für die angebotene Leistung vorgesehenen Modalitäten.\nDie Gäste sind verpflichtet, die Räumlichkeiten pfleglich zu nutzen und etwaige Unregelmäßigkeiten, Defekte oder Bedarfe, die während des Aufenthalts festgestellt werden, umgehend zu melden.\n9. Sicherheit und Haftung\nDie Gäste sind verpflichtet, die Sicherheitshinweise und etwaige von der Unterkunft bereitgestellten Anweisungen zu befolgen.\nDie Unterkunft ergreift alle in ihrem Zuständigkeitsbereich liegenden Maßnahmen, um einen sicheren und komfortablen Aufenthalt zu gewährleisten. Die Haftung für etwaige Schäden, Verluste oder Unannehmlichkeiten wird unter Berücksichtigung der jeweiligen Umstände und der geltenden gesetzlichen Bestimmungen bewertet.\nDie Gäste werden gebeten, auf ihr persönliches Eigentum sorgfältig zu achten und etwaige Probleme umgehend zu melden.\n10. Einhaltung von Vorschriften und Datenschutz\nDie Unterkunft erhebt und verarbeitet personenbezogene Daten der Gäste ausschließlich zu Zwecken, die mit der Verwaltung der Buchung, der Erbringung von Dienstleistungen und den gesetzlich vorgeschriebenen Verpflichtungen zusammenhängen, unter Einhaltung der geltenden Datenschutzbestimmungen.\n11. Annahme der Bedingungen\nMit der Bestätigung der Buchung nimmt der Gast die vorliegenden Allgemeinen Geschäftsbedingungen zur Kenntnis, unbeschadet der durch die geltende Rechtslage anerkannten Schutzrechte der Gäste.\nFür Klärungen bezüglich Buchungen, verfügbarer Dienstleistungen oder Aufenthaltsbedingungen können die Gäste die Unterkunft direkt über die auf der Website veröffentlichten offiziellen Kontaktdaten kontaktieren.\nDie Unterkunft behält sich das Recht vor, diese Bedingungen zu aktualisieren, wobei Änderungen die Rechte aus bereits bestätigten Buchungen nicht rückwirkend beeinträchtigen dürfen, soweit dies gesetzlich zulässig ist."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'faq.title', 'Preguntas frecuentes') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'faq.questions', '["¿Cuáles son los horarios de check-in y check-out en Crooked House?","¿Cuánto cuesta alojarse en Crooked House?","¿Qué actividades se pueden realizar en Crooked House?","¿A qué distancia está Crooked House del centro de Grandola ed Uniti?","¿Es Crooked House una estructura adecuada para familias?","¿Qué es la tasa turística?","¿Por qué debo introducir mis datos personales?","¿Es necesario tener un automóvil?","¿Es complicado aparcar?","¿Dónde se encuentra Crooked House?","¿Cómo se llega a Crooked House?","¿Es posible llegar a Crooked House directamente en coche?","¿Es el recorrido apto para personas con movilidad reducida?"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'faq.answers', '["El check-in en Crooked House está disponible desde las 15:30; el check-out está previsto antes de las 10:00.","El precio puede variar según la estancia, por ejemplo, según las fechas y las condiciones aplicables. Para conocer el precio, introduce las fechas de la estancia.","En Crooked House están disponibles las siguientes actividades y servicios (algunos podrían ser de pago):\n- Ciclismo\n- Senderismo\n- Campo de tenis (distancia 2,6 km)\n- Campo de golf (distancia 5,8 km)","Crooked House está a 1,9 km del centro de Grandola ed Uniti.","Sí, Crooked House es apreciada por los huéspedes que reservan estancias en familia.","La tasa turística es una contribución municipal aplicada a los huéspedes que pernoctan en los establecimientos de alojamiento del Municipio de Grandola ed Uniti (CO). El importe se calcula por persona y por noche, según el tipo de establecimiento y las tarifas establecidas por el Municipio.\n\nPara otros establecimientos de alojamiento, la tarifa publicada por el Municipio es de **2,00 € por persona y noche**, salvo posibles actualizaciones. Se prevén posibles exenciones según el reglamento municipal. La tasa es recaudada por el establecimiento de alojamiento y posteriormente ingresada al Municipio.\n\nPara más información, consulte el sitio oficial del [Municipio de Grandola ed Uniti](https://www.comune.grandolaeduniti.co.it/c013111/zf/index.php/servizi-aggiuntivi/index/index/idtesto/25).","Sus datos personales son necesarios para gestionar la reserva, identificar a los huéspedes y cumplir con las obligaciones legales, en particular con el art. 109 del T.U.L.P.S. (Real Decreto de 18 de junio de 1931, n. 773), relativo a la comunicación de los datos de identidad de los huéspedes a la Questura a través del portal Alloggiati Web. Los datos serán tratados de conformidad con el Reglamento UE 2016/679 (RGPD) y el D.Lgs. 196/2003, modificado por el D.Lgs. 101/2018, en materia de protección de datos personales.","Naggio está conectada con Menaggio, punto de partida para numerosos destinos, mediante autobús con solo dos trayectos diarios. Por este motivo, tener un coche permite desplazarse con mayor libertad y flexibilidad durante la estancia.","No, aparcar no es particularmente complicado: hay varios aparcamientos municipales gratuitos disponibles. Además, el establecimiento ofrece una plaza de aparcamiento en un garaje privado, adecuada para coches de tamaño pequeño y mediano, con una longitud máxima de 4,4 m y una anchura máxima de 1,8 m.","Crooked House se encuentra en el corazón del centro histórico, en una zona peatonal característica y libre de tráfico vehicular, ideal para quienes deseen alojarse en un ambiente tranquilo y auténtico.","Se puede llegar al establecimiento a pie mediante un breve recorrido a través del centro histórico. El trayecto transcurre por una calle empedrada, donde se pueden encontrar algunos escalones.","No, Crooked House se encuentra en una zona peatonal sin tráfico de vehículos. El último tramo para llegar al establecimiento debe realizarse a pie.","El recorrido de acceso presenta un pavimento empedrado y puede incluir algunos escalones. Estas características podrían dificultar el acceso a personas con movilidad reducida."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'servicesPage.body', 'Ofrecemos un servicio de desayuno y comidas pensado para hacer que tu estancia sea aún más agradable. Podrás empezar el día con un delicioso desayuno y disfrutar de momentos de relax saboreando platos preparados con esmero, en un ambiente acogedor y familiar.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'servicesPage.sectionTitles', '["Desayunos y comidas","Calidad, formación y seguridad"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'servicesPage.sectionBodies', '["Para hacer que tu estancia sea aún más agradable, ofrecemos bajo petición un servicio de desayuno y cena, pensado para que te sientas como en casa.\n\nPodrás empezar el día con un delicioso desayuno y terminarlo con una cena preparada con esmero, en un ambiente cálido, acogedor y familiar.\n\nPara quienes aman explorar la zona, también está disponible, bajo petición, el servicio de comida para llevar, ideal para llevar consigo durante excursiones y salidas.\n\nLos costes de los servicios y las modalidades de reserva están disponibles directamente en el establecimiento.\n\nInformación sobre intolerancias alimentarias\n\nEl establecimiento no dispone de ambientes y equipos adecuados para garantizar la ausencia de contaminación cruzada. Por lo tanto, no podemos asegurar la preparación de comidas específicas para personas con intolerancia al gluten o a la lactosa.","Nuestro establecimiento se compromete a garantizar elevados estándares de calidad, seguridad y profesionalidad, respetando la normativa vigente y mediante una actualización constante de las competencias.\n\nLa formación y las cualificaciones obtenidas dan testimonio de nuestra atención al detalle, a la gestión correcta de los servicios y a la calidad de la experiencia ofrecida a nuestros huéspedes.\n\nCertificados y cualificaciones profesionales\nFormación HACCP\nCertificado n.º 56560 del 08/09/2025.\nHabilitación para el suministro de alimentos y bebidas y para el ejercicio de la actividad comercial en el sector alimentario\nCertificado de competencia n.º E1.2025.1069853\nID sección: 137540 del 08/10/2025.\nFormación en repostería\nCurso de repostería obtenido en la Accademia Italiana Chef de Milán, en noviembre/diciembre de 2025."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'privacyPage.title', 'Política de privacidad') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'privacyPage.sectionTitles', '["POLÍTICA DE PRIVACIDAD"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'privacyPage.sectionBodies', '["POLÍTICA DE PRIVACIDAD\nTratamiento de los datos personales de los usuarios y huéspedes\n\nDe conformidad con el Reglamento (UE) 2016/679 (RGPD) y la normativa italiana aplicable, la presente política describe las modalidades de tratamiento de los datos personales de los usuarios que visitan el sitio web y de los huéspedes que reservan o se alojan en nuestra casa de vacaciones.\n\n1. Responsable del tratamiento\nEl responsable del tratamiento de los datos personales es:\n\n[Nombre y apellidos del titular / Razón social]\nNombre del establecimiento: [Nombre de la casa de vacaciones]\nDirección: [Dirección completa del establecimiento]\nCódigo fiscal / NIF: [Insertar el dato aplicable]\nCorreo electrónico: [Dirección de correo electrónico de contacto]\nTeléfono: [Número de teléfono]\n\nPara cualquier información relativa al tratamiento de los datos personales o para ejercer los derechos previstos por la normativa, es posible contactar al responsable utilizando los datos de contacto indicados anteriormente.\n\n2. Tipos de datos personales tratados\nEn el ámbito de la navegación en el sitio, la gestión de las reservas y la prestación de los servicios de alojamiento, pueden tratarse las siguientes categorías de datos:\n\nDatos identificativos: nombre, apellidos, nacionalidad y otros datos necesarios para identificar a los huéspedes.\nDatos relativos a documentos de identidad: exclusivamente aquellos necesarios para el cumplimiento de las obligaciones legales relacionadas con la hospitalidad.\nDatos de contacto: dirección de correo electrónico y número de teléfono.\nDatos relativos a la reserva: fechas de la estancia, número de huéspedes, solicitudes recibidas, confirmaciones, modificaciones y cancelaciones.\nDatos administrativos y de pago: información necesaria para la gestión de los importes, los pagos y las obligaciones fiscales y contables.\nDatos contenidos en las comunicaciones: información transmitida voluntariamente por los usuarios a través de correo electrónico, teléfono o formularios de contacto que puedan estar presentes en el sitio.\nDatos técnicos de navegación: información generada por los sistemas informáticos y los protocolos de comunicación durante la consulta del sitio, tales como la dirección IP, fecha y hora de acceso, información sobre el navegador y sobre las solicitudes realizadas, en la medida en que sean efectivamente recopilados.\nEl establecimiento no solicita datos personales que no sean pertinentes para las finalidades del tratamiento. Se invita a los usuarios a no transmitir información sensible o especial, a menos que sea estrictamente necesaria y exista una base jurídica adecuada.\n\n3. Finalidades y bases jurídicas del tratamiento\nLos datos personales se tratan para las siguientes finalidades:\n\na) Gestión de las solicitudes de información y de las reservas\n\nPara responder a las solicitudes de los usuarios, verificar la disponibilidad, formular propuestas, confirmar las reservas y gestionar eventuales variaciones o cancelaciones.\n\nBase jurídica: ejecución de medidas precontractuales solicitadas por el interesado y ejecución del contrato, de conformidad con el artículo 6, apartado 1, letra b), del RGPD.\n\nb) Gestión de la estancia y de los servicios relacionados\n\nPara organizar la acogida, comunicar la información necesaria para la estancia y gestionar los servicios solicitados por los huéspedes.\n\nBase jurídica: ejecución del contrato y, cuando proceda, el cumplimiento de obligaciones legales.\n\nc) Cumplimiento de obligaciones administrativas y normativas\n\nPara cumplir con las obligaciones previstas por la normativa aplicable a los establecimientos de alojamiento, incluidos los trámites relativos a la comunicación de los datos personales de los huéspedes a las autoridades competentes, así como las obligaciones fiscales y contables.\n\nBase jurídica: cumplimiento de obligaciones legales de conformidad con el artículo 6, apartado 1, letra c), del RGPD.\n\nd) Gestión de los pagos y protección de derechos\n\nPara verificar los pagos, gestionar eventuales disputas y proteger los derechos del establecimiento en sede extrajudicial o judicial, cuando sea necesario.\n\nBase jurídica: ejecución del contrato, cumplimiento de obligaciones legales o interés legítimo del responsable, según el caso concreto.\n\ne) Seguridad y funcionamiento del sitio web\n\nPara garantizar el correcto funcionamiento del sitio, prevenir accesos abusivos y gestionar posibles problemas técnicos.\n\nBase jurídica: interés legítimo del responsable, cuando proceda, respetando los derechos y libertades de los interesados.\n\nNo se realizan comunicaciones promocionales ni actividades de perfilado basadas en la información actualmente disponible. En caso de que se introduzcan dichas actividades, la política será actualizada y se solicitarán los consentimientos que la ley prevea.\n\n4. Reservas a través del sitio web y plataformas externas\nLas reservas pueden realizarse directamente a través de los canales del establecimiento o mediante plataformas online de intermediación y reserva.\n\nEn caso de reserva directa, los datos personales son tratados por el responsable para gestionar la solicitud, formalizar el contrato y organizar la estancia.\n\nEn caso de reserva a través de plataformas externas, los datos también pueden ser recopilados y tratados por la plataforma correspondiente, de acuerdo con sus propias condiciones contractuales e informativas de privacidad.\n\nLa plataforma y el establecimiento pueden actuar como responsables autónomos del tratamiento para sus respectivos fines. La información relativa al tratamiento realizado por la plataforma está disponible en su correspondiente política de privacidad.\n\n5. Naturaleza de la comunicación de los datos\nLa comunicación de los datos necesarios para la gestión de la reserva, la prestación de la estancia y el cumplimiento de las obligaciones legales es necesaria para tales fines.\n\nLa posible falta de comunicación de los datos indispensables puede conllevar la imposibilidad de confirmar la reserva, prestar el servicio solicitado o cumplir con las obligaciones normativas.\n\nLa comunicación de información adicional y no necesaria es facultativa.\n\n6. Modalidades de tratamiento y seguridad\nLos datos personales se tratan mediante herramientas informáticas y, cuando sea necesario, documentación en papel, de acuerdo con procedimientos adecuados a las finalidades perseguidas.\n\nEl responsable adopta medidas técnicas y organizativas proporcionales al riesgo para proteger los datos personales contra la pérdida, destrucción, acceso no autorizado, divulgación o uso ilícito.\n\nLos datos son accesibles exclusivamente al responsable y a las personas autorizadas o encargadas, dentro de sus respectivas competencias.\n\n7. Comunicación de los datos\nLos datos personales pueden ser comunicados, dentro de los límites de las finalidades indicadas, a:\n\nautoridades públicas y organismos competentes, en los casos previstos por la ley;\nasesores fiscales, contables y profesionales encargados;\nentidades bancarias y proveedores de servicios de pago;\nproveedores de hosting, mantenimiento y asistencia informática;\nplataformas de reserva e intermediarios utilizados por el huésped;\notros proveedores implicados en la gestión de la estancia, cuando sea necesario.\nLos destinatarios actúan, según el caso, como responsables autónomos o encargados del tratamiento.\n\nLos datos no se difunden indiscriminadamente al público.\n\n8. Transferencia de datos fuera del Espacio Económico Europeo\nEn caso de que, a través de plataformas externas o proveedores de servicios, se produzca una transferencia de datos personales hacia países fuera del Espacio Económico Europeo, la transferencia se realizará respetando las condiciones y las garantías previstas por el RGPD.\n\nSe puede solicitar al responsable la información relativa a las transferencias que se hayan realizado efectivamente.\n\n9. Periodo de conservación\nLos datos personales se conservan durante el tiempo necesario para alcanzar las finalidades para las que fueron recopilados y, posteriormente, durante los periodos previstos por la normativa aplicable o necesarios para la protección de los derechos del responsable.\n\nEn particular:\n\nlos datos relativos a las solicitudes y las reservas se conservan durante el tiempo necesario para la gestión de la relación y de los eventuales trámites posteriores;\nlos datos administrativos, fiscales y contables se conservan durante los plazos previstos por la normativa aplicable;\nlos datos relativos a las obligaciones de seguridad pública se conservan y gestionan según las disposiciones específicas aplicables;\nlos datos técnicos de navegación se conservan durante el periodo necesario para las finalidades de seguridad y funcionamiento del sitio, de acuerdo con las políticas adoptadas efectivamente por el proveedor del servicio.\nLos periodos específicos de conservación se definen en función de la categoría de datos, las obligaciones legales y las características de los sistemas utilizados.\n\n10. Cookies y datos de navegación\nEl sitio no utiliza, según la información actualmente disponible, herramientas adicionales de análisis estadístico, perfilado publicitario o marketing.\n\nNo obstante, la navegación podría conllevar el tratamiento de datos técnicos por parte del servidor que aloja el sitio o el uso de cookies técnicas necesarias para su funcionamiento.\n\nLas tecnologías efectivas utilizadas, incluidas las que puedan estar integradas en el sistema de reservas, deben verificarse antes de la publicación definitiva de esta política.\n\nSi el sitio utiliza exclusivamente cookies técnicas, la información correspondiente podrá incluirse en esta política. Si se utilizan herramientas de seguimiento que requieren un consentimiento previo, se adoptarán las informativas y las modalidades de gestión del consentimiento previstas por la normativa aplicable.\n\n11. Derechos de los interesados\nLos interesados pueden ejercer, en los casos y límites previstos por el RGPD, los siguientes derechos:\n\nobtener confirmación de la existencia de un tratamiento y acceder a sus propios datos personales;\nsolicitar la rectificación de datos inexactos o la integración de los incompletos;\nsolicitar la cancelación de los datos cuando concurran los supuestos legales;\nsolicitar la limitación del tratamiento;\noponerse a los tratamientos basados en el interés legítimo, por motivos relacionados con su situación particular;\nobtener la portabilidad de los datos, en los casos previstos por la ley;\nrevocar el consentimiento eventualmente prestado, sin perjuicio de la licitud del tratamiento previo a la revocación;\npresentar una reclamación ante la autoridad de protección de datos.\nLas solicitudes pueden enviarse a los datos de contacto del responsable indicados en esta política.\n\n12. Modificaciones de la política\nLa presente política puede actualizarse en caso de cambios normativos, organizativos o técnicos que afecten al tratamiento de los datos personales.\n\nLa versión actualizada se publicará en el sitio web del establecimiento.\n\nÚltima actualización: 24/10/2026.\n\nPara más información sobre el tratamiento de los datos personales, es posible contactar al responsable a través de los datos de contacto indicados en esta política."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'termsPage.title', 'Términos y condiciones') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'termsPage.sectionTitles', '["Política de cancelación","Términos y condiciones generales de estancia"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'termsPage.sectionBodies', '["Es posible cancelar la reserva hasta 10 días antes de la fecha prevista para el check-in, obteniendo el reembolso íntegro de la cantidad abonada.\n\nEn caso de cancelación realizada después de dicho plazo, no se prevé ningún reembolso.","1. Premisa\nLas presentes condiciones generales regulan las modalidades de reserva, acceso, estancia y uso de los servicios ofrecidos por el establecimiento de alojamiento.\nLa confirmación de la reserva implica la lectura y la aceptación de las condiciones expuestas en el presente documento, sin perjuicio de las disposiciones imperativas previstas por la normativa vigente.\n2. Reservas\nLas reservas pueden realizarse a través de los canales de contacto oficiales del establecimiento o mediante las plataformas autorizadas.\nLa reserva se considera confirmada según las modalidades comunicadas en el momento de la solicitud y, cuando proceda, tras el pago de la cantidad solicitada.\nCualquier petición especial deberá comunicarse con antelación y se considerará confirmada únicamente tras la aceptación por parte del establecimiento.\n3. Check-in y check-out\nLos horarios de check-in y check-out se comunican en el momento de la reserva o antes de la llegada.\nLos huéspedes están obligados a respetar los horarios acordados, salvo acuerdos distintos autorizados previamente por el establecimiento.\nCualquier solicitud de llegada anticipada o de salida tardía se evaluará en función de la disponibilidad y podrá conllevar costes adicionales, si se comunican y acuerdan previamente.\n4. Pagos\nLas tarifas, las modalidades de pago y cualquier importe que deba abonarse por adelantado se comunican en el momento de la reserva.\nLos huéspedes están obligados a respetar los plazos de pago acordados. Cualquier servicio adicional solicitado durante la estancia se facturará según las tarifas comunicadas por el establecimiento.\nLa tasa turística, si procede, se solicitará de acuerdo con las disposiciones vigentes en el municipio correspondiente.\n5. Cancelaciones y reembolsos\nLa reserva puede cancelarse hasta 10 días antes de la fecha prevista para el check-in, con derecho al reembolso íntegro de la cantidad abonada.\nEn caso de cancelación realizada en los 9 días anteriores al check-in, o en caso de no presentación (no-show), no se prevé ningún reembolso.\nLa solicitud de cancelación deberá comunicarse a través del canal utilizado para la reserva o mediante los datos de contacto oficiales del establecimiento. Se tendrá en cuenta la fecha de recepción de la comunicación.\nPara las reservas realizadas a través de plataformas externas, también podrán aplicarse las condiciones específicas previstas por la plataforma, dentro de los límites de su compatibilidad con las condiciones confirmadas y con la normativa vigente.\n6. Desayuno, comidas y servicios adicionales\nLos posibles servicios de desayuno, cena y almuerzo para llevar están disponibles bajo petición, previa verificación de disponibilidad y según las tarifas comunicadas directamente por el establecimiento.\nCualquier petición alimentaria especial deberá notificarse con antelación. El establecimiento no dispone de ambientes ni equipos adecuados para garantizar la ausencia de contaminación cruzada y, por lo tanto, no puede asegurar la preparación de comidas seguras para personas que requieran una dieta sin gluten o sin lactosa por motivos médicos.\nLos servicios adicionales están sujetos a disponibilidad y deberán acordarse previamente.\n7. Normas de comportamiento\nSe invita a los huéspedes a mantener un comportamiento respetuoso hacia los demás huéspedes, el personal, los ambientes y el entorno circundante.\nSe requiere utilizar con cuidado el mobiliario, los equipos y los espacios puestos a disposición, evitando comportamientos que puedan causar molestias o comprometer la seguridad y la tranquilidad del establecimiento.\nCualquier daño causado intencionadamente o por negligencia podrá ser cargado al responsable, previa verificación y de acuerdo con la normativa vigente.\n8. Limpieza y cuidado de los ambientes\nEl establecimiento garantiza la limpieza de los ambientes y el mantenimiento de los espacios según las modalidades previstas para el servicio ofrecido.\nLos huéspedes están obligados a utilizar los ambientes con cuidado y a informar oportunamente de cualquier anomalía, avería o necesidad detectada durante la estancia.\n9. Seguridad y responsabilidad\nLos huéspedes están obligados a respetar las indicaciones de seguridad y las posibles instrucciones proporcionadas por el establecimiento.\nEl establecimiento adopta las medidas de su competencia para garantizar una estancia segura y confortable. La responsabilidad por posibles daños, pérdidas o inconvenientes se evaluará según las circunstancias del caso y las disposiciones legales aplicables.\nSe invita a los huéspedes a cuidar con atención sus efectos personales y a informar oportunamente de cualquier problema.\n10. Cumplimiento de la normativa y protección de datos personales\nEl establecimiento recopila y trata los datos personales de los huéspedes exclusivamente para las finalidades relacionadas con la gestión de la reserva, la prestación de servicios y los cumplimientos previstos por la ley, de conformidad con la normativa aplicable en materia de protección de datos personales.\n11. Aceptación de las condiciones\nLa confirmación de la reserva implica la lectura de las presentes condiciones generales, sin perjuicio de las protecciones reconocidas a los huéspedes por la normativa vigente.\nPara cualquier aclaración relativa a las reservas, a los servicios disponibles o a las condiciones de estancia, los huéspedes pueden contactar directamente con el establecimiento a través de los datos de contacto oficiales publicados en el sitio web.\nEl establecimiento se reserva el derecho de actualizar las presentes condiciones, con la salvedad de que las modificaciones no podrán perjudicar retroactivamente los derechos derivados de las reservas ya confirmadas, dentro de los límites previstos por la ley."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'faq.title', '????? ?????????? ???????') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'faq.questions', '["Какое время заезда и выезда в Crooked House?","Сколько стоит проживание в Crooked House?","Чем можно заняться в Crooked House?","Как далеко Crooked House находится от центра Grandola ed Uniti?","Подходит ли Crooked House для семейного отдыха?","Что такое туристический налог?","Почему я должен предоставить свои персональные данные?","Необходимо ли иметь автомобиль?","Сложно ли припарковаться?","Где находится Crooked House?","Как добраться до Crooked House?","Можно ли добраться до Crooked House напрямую на автомобиле?","Подходит ли маршрут для людей с ограниченной подвижностью?"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'faq.answers', '["Заезд в Crooked House возможен с 15:30; выезд предусмотрен до 10:00.","Цена может варьироваться в зависимости от проживания, например, от дат и применимых условий. Чтобы узнать цену, введите даты проживания.","В Crooked House доступны следующие виды отдыха и услуги (некоторые могут быть платными):\n- Велоспорт\n- Пешие прогулки\n- Теннисный корт (расстояние 2,6 км)\n- Поле для гольфа (расстояние 5,8 км)","Crooked House находится в 1,9 км от центра Grandola ed Uniti.","Да, Crooked House пользуется популярностью у гостей, бронирующих семейный отдых.","Туристический налог — это муниципальный сбор, применяемый к гостям, проживающим в объектах размещения в муниципалитете Grandola ed Uniti (CO). Сумма рассчитывается на человека за одну ночь в соответствии с типом объекта и тарифами, установленными муниципалитетом.\n\nДля других объектов размещения тариф, опубликованный муниципалитетом, составляет **2,00 € с человека за ночь**, если не будет внесено обновлений. Предусмотрены возможные освобождения в соответствии с муниципальным регламентом. Налог взимается объектом размещения и впоследствии перечисляется в муниципалитет.\n\nДля получения дополнительной информации посетите официальный сайт [Comune di Grandola ed Uniti](https://www.comune.grandolaeduniti.co.it/c013111/zf/index.php/servizi-aggiuntivi/index/index/idtesto/25).","Ваши персональные данные необходимы для управления бронированием, идентификации гостей и выполнения законодательных обязательств, в частности, статьи 109 T.U.L.P.S. (Королевский указ от 18 июня 1931 г., № 773), касающейся передачи данных о гостях в полицию (Questura) через портал Alloggiati Web. Данные будут обрабатываться в соответствии с Регламентом ЕС 2016/679 (GDPR) и Законодательным декретом 196/2003, с изменениями, внесенными Законодательным декретом 101/2018, в области защиты персональных данных.","Naggio связан с Менаджо, отправной точкой для многих направлений, посредством автобуса, который ходит всего два раза в день. По этой причине наличие автомобиля позволит перемещаться с большей свободой и гибкостью во время пребывания.","Нет, парковка не представляет особой сложности: доступны различные бесплатные муниципальные парковки. Кроме того, объект предлагает парковочное место в частном гараже, подходящее для автомобилей малого и среднего размера, с максимальной длиной 4,4 м и максимальной шириной 1,8 м.","Crooked House находится в самом сердце исторического центра, в характерной пешеходной зоне без автомобильного движения, что идеально подходит для тех, кто хочет остановиться в спокойной и аутентичной обстановке.","До объекта можно добраться пешком по короткому маршруту через исторический центр. Путь проходит по мощеной улице, на которой могут встречаться ступени.","Нет, Crooked House находится в пешеходной зоне без автомобильного движения. Последний участок пути до объекта необходимо пройти пешком.","Подъездной путь имеет мощеное покрытие и может включать несколько ступеней. Эти особенности могут затруднить доступ для людей с ограниченной подвижностью."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'servicesPage.body', 'Мы предлагаем услуги завтрака и питания, разработанные для того, чтобы сделать ваше пребывание еще более приятным. Вы сможете начать день с вкусного завтрака и насладиться моментами отдыха, пробуя блюда, приготовленные с заботой, в уютной и домашней атмосфере.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'servicesPage.sectionTitles', '["Завтраки и питание","Качество, обучение и безопасность"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'servicesPage.sectionBodies', '["Чтобы сделать ваше пребывание еще более приятным, мы предлагаем по запросу услуги завтрака и ужина, призванные дать вам почувствовать себя как дома.\n\nВы сможете начать день с вкусного завтрака и завершить его тщательно приготовленным ужином в теплой, уютной и домашней атмосфере.\n\nДля тех, кто любит исследовать окрестности, также доступна по запросу услуга обеда с собой, что идеально подходит для прогулок и экскурсий.\n\nСтоимость услуг и способы бронирования можно узнать непосредственно в объекте размещения.\n\nИнформация о пищевой непереносимости\n\nОбъект размещения не располагает помещениями и оборудованием, позволяющими гарантировать отсутствие перекрестного загрязнения. Поэтому мы не можем гарантировать приготовление специальных блюд для людей с непереносимостью глютена или лактозы.","Наше заведение стремится обеспечивать высокие стандарты качества, безопасности и профессионализма, соблюдая действующие нормы и постоянно повышая квалификацию.\n\nОбучение и полученные квалификации свидетельствуют о нашем внимании к деталям, правильному управлению услугами и качеству опыта, предлагаемого нашим гостям.\n\nПрофессиональные сертификаты и квалификации\nОбучение HACCP\nСертификат № 56560 от 08/09/2025.\nРазрешение на подачу продуктов питания и напитков и ведение коммерческой деятельности в пищевом секторе\nСертификат компетенции № E1.2025.1069853\nID раздела: 137540 от 08/10/2025.\nОбучение кондитерскому делу\nКурс кондитерского дела, пройденный в Accademia Italiana Chef di Milano в ноябре/декабре 2025 года."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'privacyPage.title', 'Политика конфиденциальности') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'privacyPage.sectionTitles', '["ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'privacyPage.sectionBodies', '["ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ\nОбработка персональных данных пользователей и гостей\n\nВ соответствии с Регламентом (ЕС) 2016/679 (GDPR) и применимым итальянским законодательством, настоящая политика описывает способы обработки персональных данных пользователей, посещающих веб-сайт, и гостей, бронирующих проживание или останавливающихся в нашем доме для отдыха.\n\n1. Оператор обработки данных\nОператором обработки персональных данных является:\n\n[Имя и фамилия владельца / Юридическое лицо]\nНазвание объекта: [Название дома для отдыха]\nАдрес: [Полный адрес объекта]\nИНН / НДС: [Введите применимые данные]\nE-mail: [Контактный адрес электронной почты]\nТелефон: [Номер телефона]\n\nДля получения любой информации, касающейся обработки персональных данных, или для осуществления прав, предусмотренных законодательством, вы можете связаться с оператором, используя указанные выше контактные данные.\n\n2. Категории обрабатываемых персональных данных\nВ рамках навигации по сайту, управления бронированиями и предоставления услуг проживания могут обрабатываться следующие категории данных:\n\nИдентификационные данные: имя, фамилия, национальность и другие данные, необходимые для идентификации гостей.\nДанные документов, удостоверяющих личность: исключительно данные, необходимые для выполнения законодательных обязательств, связанных с приемом гостей.\nКонтактные данные: адрес электронной почты и номер телефона.\nДанные, связанные с бронированием: даты проживания, количество гостей, полученные запросы, подтверждения, изменения и отмены.\nАдминистративные и платежные данные: информация, необходимая для управления вознаграждениями, платежами, а также для выполнения налоговых и бухгалтерских обязательств.\nДанные, содержащиеся в сообщениях: информация, добровольно передаваемая пользователями через электронную почту, телефон или контактные формы, которые могут присутствовать на сайте.\nТехнические данные о навигации: информация, генерируемая информационными системами и протоколами связи во время просмотра сайта, такая как IP-адрес, дата и время доступа, информация о браузере и сделанных запросах, в пределах того, что фактически собирается.\nОбъект размещения не запрашивает персональные данные, не имеющие отношения к целям обработки. Пользователям рекомендуется не передавать конфиденциальную или особые категории данных, за исключением случаев, когда это строго необходимо и имеется надлежащее правовое основание.\n\n3. Цели и правовые основания обработки\nПерсональные данные обрабатываются для следующих целей:\n\na) Управление запросами информации и бронированиями\n\nДля ответа на запросы пользователей, проверки наличия свободных мест, формирования предложений, подтверждения бронирований и управления любыми изменениями или отменами.\n\nПравовое основание: выполнение преддоговорных мер, запрошенных субъектом данных, и выполнение договора в соответствии со статьей 6, параграф 1, буква b), GDPR.\n\nb) Управление проживанием и сопутствующими услугами\n\nДля организации приема, сообщения информации, необходимой для проживания, и управления услугами, запрошенными гостями.\n\nПравовое основание: выполнение договора и, где применимо, выполнение юридических обязательств.\n\nc) Административные и нормативные обязательства\n\nДля выполнения обязательств, предусмотренных законодательством, применимым к объектам размещения, включая обязательства по передаче личных данных гостей компетентным органам, а также налоговые и бухгалтерские обязательства.\n\nПравовое основание: выполнение юридических обязательств в соответствии со статьей 6, параграф 1, буква c), GDPR.\n\nd) Управление платежами и защита прав\n\nДля проверки платежей, управления возможными претензиями и защиты прав объекта размещения в досудебном или судебном порядке, когда это необходимо.\n\nПравовое основание: выполнение договора, выполнение юридических обязательств или законный интерес оператора, в зависимости от конкретного случая.\n\ne) Безопасность и функционирование веб-сайта\n\nДля обеспечения правильной работы сайта, предотвращения несанкционированного доступа и решения возможных технических проблем.\n\nПравовое основание: законный интерес оператора, где это применимо, при соблюдении прав и свобод субъектов данных.\n\nРекламные сообщения или деятельность по профилированию на основе имеющейся на данный момент информации не осуществляются. В случае введения такой деятельности политика будет обновлена, и будут запрошены соответствующие согласия, предусмотренные законом.\n\n4. Бронирование через сайт и внешние платформы\nБронирование может быть осуществлено напрямую через каналы объекта размещения или через онлайн-платформы посредничества и бронирования.\n\nВ случае прямого бронирования персональные данные обрабатываются оператором для управления запросом, заключения договора и организации проживания.\n\nВ случае бронирования через внешние платформы данные могут собираться и обрабатываться также соответствующей платформой в соответствии с ее собственными условиями договора и политикой конфиденциальности.\n\nПлатформа и объект размещения могут действовать как независимые операторы обработки данных для своих соответствующих целей. Информация, касающаяся обработки, осуществляемой платформой, доступна в соответствующей политике конфиденциальности платформы.\n\n5. Характер предоставления данных\nПредоставление данных, необходимых для управления бронированием, обеспечения проживания и выполнения юридических обязательств, необходимо для соответствующих целей.\n\nВозможный отказ от предоставления необходимых данных может привести к невозможности подтверждения бронирования, предоставления запрошенной услуги или выполнения нормативных обязательств.\n\nПредоставление дополнительной и ненужной информации является добровольным.\n\n6. Способы обработки и безопасность\nПерсональные данные обрабатываются с помощью ИТ-инструментов и, при необходимости, бумажной документации, в соответствии с процедурами, адекватными преследуемым целям.\n\nОператор принимает технические и организационные меры, пропорциональные риску, чтобы защитить персональные данные от потери, уничтожения, несанкционированного доступа, разглашения или незаконного использования.\n\nДоступ к данным имеют исключительно оператор и любые уполномоченные или назначенные лица в пределах их соответствующих компетенций.\n\n7. Передача данных\nПерсональные данные могут передаваться в пределах указанных целей:\n\nгосударственным органам и компетентным организациям в случаях, предусмотренных законом;\nналоговым консультантам, бухгалтерам и назначенным специалистам;\nбанковским учреждениям и поставщикам платежных услуг;\nпровайдерам хостинга, технического обслуживания и ИТ-поддержки;\nплатформам бронирования и посредникам, используемым гостем;\nдругим поставщикам, участвующим в управлении проживанием, когда это необходимо.\nПолучатели данных выступают, в зависимости от случая, в качестве независимых операторов или лиц, которым поручена обработка.\n\nДанные не распространяются без разбора среди общественности.\n\n8. Передача данных за пределы Европейской экономической зоны\nВ случае, если через внешние платформы или поставщиков услуг происходит передача персональных данных в страны за пределы Европейской экономической зоны, такая передача будет осуществляться с соблюдением условий и гарантий, предусмотренных GDPR.\n\nИнформацию о любых фактически осуществленных передачах можно запросить у оператора.\n\n9. Период хранения\nПерсональные данные хранятся в течение времени, необходимого для достижения целей, для которых они были собраны, а затем в течение периодов, предусмотренных применимым законодательством или необходимых для защиты прав оператора.\n\nВ частности:\n\nданные, связанные с запросами и бронированиями, хранятся в течение времени, необходимого для управления отношениями и выполнения любых последующих обязательств;\nадминистративные, налоговые и бухгалтерские данные хранятся в течение сроков, предусмотренных применимым законодательством;\nданные, связанные с обязательствами в области общественной безопасности, хранятся и обрабатываются в соответствии с применимыми специальными положениями;\nтехнические данные о навигации хранятся в течение периода, необходимого для целей безопасности и функционирования сайта, в соответствии с политиками, фактически принятыми поставщиком услуг.\nКонкретные периоды хранения определяются в зависимости от категории данных, юридических обязательств и характеристик используемых систем.\n\n10. Cookie и данные о навигации\nСогласно имеющейся на данный момент информации, сайт не использует дополнительные инструменты статистического анализа, рекламного профилирования или маркетинга.\n\nОднако навигация может повлечь за собой обработку технических данных сервером, на котором размещен сайт, или использование технических cookie, необходимых для его функционирования.\n\nФактические используемые технологии, включая те, которые могут быть интегрированы в систему бронирования, должны быть проверены перед окончательной публикацией настоящей политики.\n\nЕсли сайт использует исключительно технические cookie, соответствующая информация может быть включена в настоящую политику. Если используются инструменты отслеживания, требующие предварительного согласия, будут приняты информационные сообщения и методы управления согласием, предусмотренные применимым законодательством.\n\n11. Права субъектов данных\nСубъекты данных могут осуществлять в случаях и пределах, предусмотренных GDPR, следующие права:\n\nполучать подтверждение факта обработки и иметь доступ к своим персональным данным;\nзапрашивать исправление неточных данных или дополнение неполных;\nзапрашивать удаление данных при наличии соответствующих условий;\nзапрашивать ограничение обработки;\nвозражать против обработки, основанной на законном интересе, по причинам, связанным с их особым положением;\nполучать переносимость данных в случаях, предусмотренных законом;\nотзывать предоставленное согласие без ущерба для законности обработки, предшествовавшей отзыву;\nподать жалобу в Гаранта по защите персональных данных.\nЗапросы могут быть направлены по контактным данным оператора, указанным в настоящей политике.\n\n12. Изменения в политике\nНастоящая политика может быть обновлена в случае изменений в законодательстве, организации или технических аспектах, влияющих на обработку персональных данных.\n\nОбновленная версия будет опубликована на веб-сайте объекта размещения.\n\nПоследнее обновление: 24.10.2026.\n\nДля получения дополнительной информации об обработке персональных данных вы можете связаться с оператором по контактам, указанным в настоящей политике."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'termsPage.title', 'Условия использования') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'termsPage.sectionTitles', '["Политика отмены бронирования","Общие правила и условия проживания"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('ru', 'termsPage.sectionBodies', '["Бронирование можно отменить не позднее чем за 10 дней до предполагаемой даты заезда с получением полного возврата уплаченной суммы.\n\nВ случае отмены бронирования после этого срока возврат средств не предусмотрен.","1. Введение\nНастоящие общие условия регулируют порядок бронирования, доступа, проживания и использования услуг, предлагаемых объектом размещения.\nПодтверждение бронирования означает ознакомление и принятие условий, изложенных в настоящем документе, за исключением императивных положений, предусмотренных действующим законодательством.\n2. Бронирование\nБронирование может быть осуществлено через официальные каналы связи объекта или через авторизованные платформы.\nБронирование считается подтвержденным в соответствии с порядком, сообщенным в момент запроса, и, если предусмотрено, после внесения требуемой суммы.\nЛюбые особые пожелания должны быть сообщены заранее и будут считаться подтвержденными только после одобрения объектом размещения.\n3. Заезд и выезд\nВремя заезда и выезда сообщается в момент бронирования или перед прибытием.\nГости обязаны соблюдать согласованное время, если иное не было предварительно согласовано с объектом размещения.\nЛюбые запросы на ранний заезд или поздний выезд будут рассматриваться в зависимости от наличия возможности и могут потребовать дополнительной оплаты, если они были сообщены и согласованы заранее.\n4. Оплата\nТарифы, способы оплаты и любые суммы, подлежащие предоплате, сообщаются в момент бронирования.\nГости обязаны соблюдать согласованные сроки оплаты. Любые дополнительные услуги, запрошенные во время проживания, будут тарифицироваться согласно расценкам, предоставленным объектом размещения.\nГородской налог, если он применим, взимается в соответствии с правилами, действующими в соответствующем муниципалитете.\n5. Отмена и возврат средств\nБронирование может быть отменено не позднее чем за 10 дней до предполагаемой даты заезда с правом на полный возврат уплаченной суммы.\nВ случае отмены бронирования в течение 9 дней до заезда или в случае неявки (no-show) возврат средств не предусмотрен.\nЗапрос на отмену должен быть направлен через канал, использованный для бронирования, или по официальным контактным данным объекта. Датой отмены считается дата получения сообщения.\nДля бронирований, осуществленных через сторонние платформы, могут применяться также особые условия, предусмотренные этой платформой, в пределах их совместимости с подтвержденными условиями и действующим законодательством.\n6. Завтрак, питание и дополнительные услуги\nЗавтрак, ужин и ланч-боксы предоставляются по запросу, при условии наличия возможности и согласно тарифам, сообщенным непосредственно объектом размещения.\nО любых особых требованиях к питанию необходимо сообщать заранее. Объект размещения не располагает помещениями и оборудованием, позволяющими гарантировать отсутствие перекрестного загрязнения, и, следовательно, не может гарантировать приготовление безопасной пищи для лиц, нуждающихся в безглютеновой или безлактозной диете по медицинским показаниям.\nДополнительные услуги предоставляются при наличии возможности и должны быть согласованы заранее.\n7. Правила поведения\nГостей просят проявлять уважение к другим гостям, персоналу, помещениям и окружающей обстановке.\nТребуется бережно относиться к мебели, оборудованию и предоставляемым помещениям, избегая поведения, которое может причинить беспокойство или нарушить безопасность и спокойствие объекта размещения.\nЛюбой ущерб, причиненный умышленно или по неосторожности, может быть взыскан с ответственного лица после проверки и в соответствии с действующим законодательством.\n8. Чистота и содержание помещений\nОбъект размещения гарантирует чистоту помещений и содержание пространств в соответствии с правилами предоставляемого сервиса.\nГости обязаны бережно пользоваться помещениями и своевременно сообщать о любых неисправностях, поломках или возникших потребностях во время проживания.\n9. Безопасность и ответственность\nГости обязаны соблюдать указания по безопасности и любые инструкции, предоставляемые объектом размещения.\nОбъект размещения принимает меры в рамках своей компетенции для обеспечения безопасного и комфортного проживания. Ответственность за любой ущерб, утрату вещей или неудобства будет оцениваться в зависимости от обстоятельств дела и в соответствии с применимыми законодательными нормами.\nГостям рекомендуется внимательно следить за своими личными вещами и своевременно сообщать о любых проблемах.\n10. Соблюдение законодательства и защита персональных данных\nОбъект размещения собирает и обрабатывает персональные данные гостей исключительно в целях, связанных с управлением бронированием, предоставлением услуг и выполнением требований закона, в соответствии с применимым законодательством о защите персональных данных.\n11. Принятие условий\nПодтверждение бронирования означает ознакомление с настоящими общими условиями, без ущерба для прав, гарантированных гостям действующим законодательством.\nДля получения любых разъяснений относительно бронирования, доступных услуг или условий проживания гости могут напрямую связаться с объектом размещения по официальным контактам, опубликованным на сайте.\nОбъект размещения оставляет за собой право обновлять настоящие условия, при условии, что изменения не могут иметь обратную силу и не должны нарушать права, вытекающие из уже подтвержденных бронирований, в пределах, предусмотренных законом."]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
